def get_engine(cdir, general=False, tid=None, create=True):
    if general:
        tid = str(tid or "1")
        if not re.fullmatch(r"\d{1,6}", tid):
            return None
        if create and tid not in _load_terms(cdir):
            return None
    key = cdir + (f"||general||{tid}" if general else "")
    with ENGINES_LOCK:
        if key not in ENGINES:
            if not create:
                return None
            if sum(1 for e in ENGINES.values() if e.alive()) >= MAX_LIVE_ENGINES:
                return None
            ENGINES[key] = Engine(cdir, permission_mode=CONFIG["permission_mode"],
                                  fake=CONFIG["fake"], steward=CONFIG["steward"],
                                  general=general, tid=tid if general else None)
        return ENGINES[key]

def _contract(self):
    if self.code_job:
        return CODER_CONTRACT
    if self.effort_on():
        return EFFORT_DUTY + CONTRACT + EFFORT_RULES
    return SMALL_DUTY + CONTRACT

def say(self, text, human=True, question_id=None, goal=None):
    text = (text or "").strip()
    if not text:
        return {"ok": False, "error": "empty"}
    if human:   # W1 of the two-lane plan (2026-10-05): the queue wait is measured from his message's arrival
        self._human_arrivals = (getattr(self, "_human_arrivals", None) or [])[-20:] + [time.time()]
    goal = str(goal or "").strip() or None      # W2 v2: said inside a goal's place — recorded with the tag, sent with the scope
    goal_name = ""
    if goal:
        try:
            from steward_cockpit import campaign_acts as _acts
            _g = _acts._step(self.dir, goal)
            goal_name = str((_g or {}).get("name") or "")
        except Exception:
            goal_name = ""
        if not goal_name:
            goal = None
    if human and not self.general and not self.code_job:
        # R2/R3 (2026-10-04): his words set the mode and stop a code job; the message still goes to the steward
        if _EFFORT_ON.search(text) or _EFFORT_OFF.search(text):
            on = bool(_EFFORT_ON.search(text))
            _update_state(self.skey(), {"effort_mode": on})
            self._emit({"t": "sys", "text": "effort rules on - the full plan discipline applies here" if on else "small mode - small changes stay small; real work goes to a code job"})
        if _STOP_CODER.match(text):
            try:
                from steward_cockpit import code_jobs as _cj
                from steward_cockpit import steward_routes as _sr
                r = _cj.stop(self.dir, engine_lookup=lambda wt: _sr.get_engine(wt, general=True, tid="1", create=False))
                self._emit({"t": "sys", "text": ("code job stopped; its work so far stays on branch " + r["branch"]) if r.get("ok") else ("no code job to stop: " + str(r.get("error")))})
            except Exception as e:
                self._emit({"t": "sys", "text": "the code job could not be stopped: %s" % e})
    answer_context = None
    if question_id:
        answer_context = next((q for q in self._question_contexts(self._attention()) if q["id"] == question_id), None)
        if not answer_context:
            return {"ok": False, "error": "This question changed or was resolved. Open the current question before answering."}
    if not self.alive():
        ok, why = self.wake()
        if not ok:
            from steward_cockpit import maintenance
            if human and maintenance.is_active():
                # Wave 1.6: accepted durably, delivered after activation.
                with self._lock:
                    if not self._record_conversation("john", text, goal=goal):
                        return {"ok": False, "error": "your message was not accepted because durable conversation storage failed"}
                    self.queue.append(_scoped_text(text, goal, goal_name))
                    if not self._persist_queue():
                        self.queue.pop()
                        return {"ok": False, "error": "could not durably queue your text"}
                    self._emit({"t": "john", "text": text})
                    self._emit({"t": "sys", "text": "queued - maintenance in progress; delivered when the steward resumes"})
                return {"ok": True, "queued": True, "maintenance": True}
            if human:
                # W2e (2026-09-30, John: "not delivered - your text is back in the box" after a restart): a wake that
                # failed (the provider deferred, the settings unreadable, the CLI gone) keeps his words durably; they
                # go on the next wake - never his to retype. A control that cannot be delivered is simply not sent.
                with self._lock:
                    if not self._record_conversation("john", text, goal=goal):
                        return {"ok": False, "error": "your message was not accepted because durable conversation storage failed"}
                    self.queue.append(_scoped_text(text, goal, goal_name))
                    if not self._persist_queue():
                        self.queue.pop()
                        return {"ok": False, "error": "could not durably queue your text"}
                    self._emit({"t": "john", "text": text})
                    self._emit({"t": "sys", "text": "the steward could not wake just now (" + str(why) + ") - your text is kept and goes when it wakes"})
                return {"ok": True, "queued": True, "kept": True}
            return {"ok": False, "error": why}

    # One ingress transaction: update the human/control state, append the
    # visible event, and either queue or write stdin under the same lock as
    # result-boundary arbitration. A displayed human turn therefore can
    # never be followed by an automatic nudge/drive write before it lands.
    wait = self._attention() if human else {}
    with self._lock:
        control = ""
        if human:
            if question_id and not any(q["id"] == question_id for q in self._question_contexts(wait)):
                return {"ok": False, "error": "Question is no longer current"}
            if not self._record_conversation("john", text, goal=goal):
                return {"ok": False, "error": "your message was not accepted because durable conversation storage failed"}
            # Only bare UI commands are controls. "go with option B" and
            # "hold on" are substantive words, not drive switches.
            low = text.lower().rstrip(".!").strip()
            if low == "go":
                self.drive = True
                self.auto_count = 0
                control = "go"
            elif low in ("pause", "stop", "hold"):
                self.drive = False
                control = "pause"
            self.last_say = time.time()
            self.john_msgs += 1
            self._human_asked = text.rstrip().endswith("?")
            self._answer_nudged = False
            self._decision_nudged = False
            if answer_context:
                entry = {"question":answer_context, "answer":text, "answered_at":time.time(),
                         "status":"response_recorded", "source_ref":"Cockpit conversation"}
                history = (getattr(self, "question_history", []) + [entry])[-100:]
                if not _update_state(self.skey(), {"question_history":history}):
                    return {"ok": False, "error": "Question response context could not be saved"}
                self.question_history = history
                if not (answer_context.get("authorization_scope") or {}).get("request_id"):
                    self._strip_clear_wait()    # a decision answered: the wait on John is over (C2)
                    try:
                        from . import horizon as _horizon
                        _horizon.refresh(self.dir, "answered")   # W3 (2026-09-28): the line follows the answer
                    except Exception:
                        pass

            if wait.get("managed_refinement"):
                # Conversation and drive controls never resolve a review.
                # Only a lifecycle operation can change its pending request.
                self.open_question = ""
                self.open_question_kind = ""
                if control and self._question_contexts(wait):
                    self._emit({"t": "john", "text": text})
                    return {"ok": True, "queued": False, "control_only": True}
            elif self.open_question:
                kind = (self.open_question_kind
                        or _question_kind(self.open_question))
                if control and kind != "drive_offer":
                    # Drive is an interface command, not an answer. Never
                    # put a bare approval-shaped token on model stdin.
                    self._emit({"t": "john", "text": text})
                    self._emit({"t": "sys", "text":
                                ("drive armed" if control == "go"
                                 else "drive paused")
                                + " - still waiting on: "
                                + self.open_question})
                    return {"ok": True, "queued": False,
                            "control_only": True}
                self.open_question = ""
                self.open_question_kind = ""
                _update_state(self.skey(), {
                    "open_question": "",
                    "open_question_kind": "",
                    "question_context": None,
                })
            if not control:
                self.question_context = None
                _update_state(self.skey(), {"question_context":None})

        self._emit({"t": "john" if human else "sys", "text": text})
        text = _scoped_text(text, goal, goal_name)      # the model is told which goal he is in; his shown words stay his own
        if answer_context:
            text += ("\n\n(answer context, not a new request) This response concerns only the saved question and "
                     "versions below. Recheck applicability before acting; this is not automatic acceptance.\n" +
                     json.dumps(answer_context, ensure_ascii=False))
        # (2026-09-05, John: "the plan does not get updated") while the
        # roadmap is behind the plan documents, his turn carries the drift
        # line on the model's stdin - his displayed words stay his own.
        if self.busy:
            # queued RAW: the drift line is computed when this is delivered
            # (a line computed now can be false by then — journal 0111)
            self.queue.append(text)
            if not self._persist_queue():
                self.queue.pop()
                self.broken = True
                self._emit({"t": "sys", "text":
                            "queue persistence failed - your text was "
                            "not accepted; please retry after storage "
                            "is healthy"})
                return {"ok": False,
                        "error": "could not durably queue your text"}
            if human and self._turn_origin != "human":
                # Wave 1.2: his words outrank a self-started turn (drive,
                # nudge, stand-up). The turn is ended, its outcome recorded
                # as uncertain, and his message goes next.
                self._emit({"t": "sys", "text": "your message arrived during a self-started turn - ending that turn; your message goes next"})
                self._interrupt_turn_locked("human message arrived during a self-started turn")
                ok, why = self._wake_locked(fresh=False, seed=None)
                if not ok:
                    self._emit({"t": "sys", "text": "steward could not resume after the interruption: " + str(why) + "; your message is queued"})
                return {"ok": True, "queued": bool(self.queue), "interrupted": True}
            # R1 (steward responsiveness, 2026-10-04): the receipt names what the steward is on and since
            # when, and carries "Take this now" (interrupt, then deliver his message at once)
            if human:
                self._emit({"t": "sys", "text": self._queued_receipt(), "take_now": True})
            else:
                self._emit({"t": "sys", "text": "queued - the steward is mid-turn; it will be delivered next"})
            return {"ok": True, "queued": True}
        from steward_cockpit import maintenance
        if human and maintenance.is_active():
            # Wave 1.6 (Grok R1 F3): an alive, idle steward behind the
            # barrier takes no new turn; his words wait durably.
            self.queue.append(text)
            if not self._persist_queue():
                self.queue.pop()
                return {"ok": False, "error": "could not durably queue your text"}
            self._emit({"t": "sys", "text": "queued - maintenance in progress; delivered when the steward resumes"})
            return {"ok": True, "queued": True, "maintenance": True}
        ok = self._send_locked(text + (self._plan_drift_suffix() if (human and not self.general and self.effort_on()) else ""),
                               origin="human" if human else "control")
    if not ok:
        return {"ok": False, "error": "delivery failed - your text was not sent"}
    return {"ok": True, "queued": False}

def _guard_turn(self, block):
    """R2/R3: end a small-mode turn that has grown past the step cap (it is handed to a code job), and a turn
    that writes into a repository a running code job owns (one writer). True when the turn was ended."""
    if self.general or self.code_job or self.fake or not self.busy:
        return False
    reason, note = "", ""
    inp = block.get("input") or {}
    paths = [p for p in ([inp.get("file_path")] + list(inp.get("paths") or [])) if isinstance(p, str) and p.strip()]
    try:
        from steward_cockpit import code_jobs as _cj
        owned = _cj.active_repos()
    except Exception:
        owned = []
    hit = []
    if owned:
        name = block.get("name") or ""
        absolute = [p if os.path.isabs(p) else os.path.join(self.dir, p) for p in paths]
        if name in ("Write", "Edit", "NotebookEdit", "file_change", "apply_patch"):
            hit = [p for p in absolute if any(_cj.inside(p, r) for r in owned)]
        elif name in _SHELL_TOOLS:
            # a shell or exec call: a write when it runs inside a busy repository, or names one with a writing verb
            cmd = json.dumps(inp, ensure_ascii=False)[:6000]
            if any(_cj.inside(self.dir, r) for r in owned) and _WRITE_VERBS.search(cmd):
                hit = [self.dir]
            else:
                flat = cmd.replace("\\\\", "/").replace("\\", "/").lower()
                for r in owned:
                    rr = str(r).replace("\\", "/").lower().rstrip("/")
                    if re.search(re.escape(rr) + r"(?:/|[\"' ]|$)", flat) and _WRITE_VERBS.search(cmd):
                        hit = [r]
                        break
        if hit:
            reason = "one writer: a code job is working on that repository"
            note = ("(interface - not John) Your last turn was ended: it wrote %s while a code job owns that "
                    "repository. Do not write there until the job reports; tell John in one line." % hit[0])
    if not reason and getattr(self, "_turn_origin", "human") == "human" and self._turn_tools > STEP_CAP and not self.effort_on():
        reason = "past %d tool calls: larger than a small change" % STEP_CAP
        note = ("(interface - not John) Your last turn was ended after %d tool calls: this is larger than a small "
                "change. Hand it to a code job now (tools/steward_code_job.py start, with a short brief and a check), "
                "then tell John in one line what the coder is doing." % self._turn_tools)
    if not reason:
        return False
    with self._lock:
        self._emit({"t": "sys", "text": "%s ended its turn (%s)" % (self.steward or "The steward", reason)})
        out = self._interrupt_turn_locked(reason)
        if isinstance(out, dict) and out.get("ok"):
            self.queue.insert(0, note)
            self._persist_queue()
            self._wake_locked(fresh=False, seed=None)
    return True

def _select_available_policy(self, settings, target, excluded=()):
    """Bounded prelaunch selection, exclusively among dashboard families."""
    import model_policy
    ladder = list(dict.fromkeys([target] + [settings[k] for k in ("coding_family", "review_family", "default_cli")]))
    if settings.get("provider_preferences", {}).get("family"):
        ladder = [target]  # An explicit account choice never borrows another subscription.
    failed = []
    for family in ladder:
        if family in excluded:
            continue
        try:
            if family not in ("claude", "chatgpt", "grok"):
                raise RuntimeError("native cockpit capability contract is not verified")
            if family == "grok" and not (HERE / "grok_turn_bridge.py").is_file():
                raise RuntimeError("native Grok cockpit adapter is unavailable")
            if self.provider_connection["family"] == family and (not self.provider_connection["native_default"] or self.provider_quality):
                import provider_setup as _provider_setup
                bound_settings = {**settings, "provider_preferences": {**settings["provider_preferences"],
                                 "quality": {family: self.provider_quality} if self.provider_quality else {}}}
                selection = _provider_setup.resolve_quality(family, bound_settings, self.provider_connection)
            else:
                selection = model_policy.resolve(family, settings=settings)
        except (ValueError, RuntimeError) as exc:
            failed.append(family)
            self._journal_routing(action="unavailable", family=family,
                                  message=family + " preflight unavailable: " + str(exc))
            continue
        if family != target:
            self._journal_routing(action="failover", requested=target, actual_family=family,
                                  model_served=None, cross_model=False,
                                  message=target + " -> " + family + "; selected-provider fallback, cross_model:false")
            self.policy_override = {"family": family, "revision": settings["settings_revision"],
                                    "reason": "visible_failover", "failed_families": list(excluded)}
        return family, selection
    self._journal_routing(action="halt", message="No capable selected cockpit provider remains")
    raise RuntimeError("No capable selected cockpit provider remains; check subscription health")

def record_status_ack(self, at=""):
    """The wakeup-delivery lesson, mechanized: the pane POSTs an ack AFTER
    it RENDERS a status, so delivery is a receipt, not a hope. The first
    ack ever flips channel_verified — the one-time 'this channel reaches
    John' acknowledgment; every ack updates the render-leg log."""
    try:
        now = time.strftime("%Y-%m-%dT%H:%M:%S")
        state = {"first": False}
        def _mut(d):
            state["first"] = not d.get("channel_verified")
            d["channel_verified"] = True
            if state["first"]:
                d["channel_verified_at"] = now
            d["last_render_ack_at"] = now
            d["last_acked_status_at"] = str(at or "")
            d["render_acks"] = int(d.get("render_acks", 0)) + 1
        self._delivery_patch(_mut)
        return {"ok": True, "channel_verified_first_time": state["first"]}
    except Exception as e:
        return {"ok": False, "error": f"{type(e).__name__}: {e}"}

def _retry_refinement_handoffs(self):
    """Drain one saved observation through the existing ledger, never under the stdin lock."""
    if not getattr(self, "_pending_refinement_handoffs", {}):
        return True
    if not self._refinement_retry_lock.acquire(blocking=False):
        return False
    try:
        with self._refinement_pending_lock:
            if not self._pending_refinement_handoffs:
                return True
            producer_id, payload = next(iter(self._pending_refinement_handoffs.items()))
            # A failed session-state write must not silently orphan an observation.
            if not _update_state(self.skey(), {
                    "pending_refinement_handoffs": self._pending_refinement_handoffs}):
                return False
        from steward_cockpit.producer_handoff import record_handoff
        try:
            receipt = record_handoff(self.dir, **payload)
        except Exception as exc:
            receipt = {"ok": False, "error": "handoff-recording-failed",
                       "detail": type(exc).__name__}
        with self._refinement_pending_lock:
            remaining = dict(self._pending_refinement_handoffs)
            if receipt.get("ok"):
                remaining.pop(producer_id, None)
            acknowledged = _update_state(self.skey(), {
                "pending_refinement_handoffs": remaining,
                "refinement_handoff": receipt})
            if acknowledged:
                self._pending_refinement_handoffs = remaining
        error = (receipt.get("error") if not receipt.get("ok") else
                 "handoff-receipt-persistence-failed" if not acknowledged else None)
        if error and error != self._refinement_handoff_error:
            self._emit({"t": "sys", "text": "Work completed, but its refinement handoff needs repair: " + str(error)})
        self._refinement_handoff_error = error
        return bool(receipt.get("ok") and acknowledged)
    finally:
        self._refinement_retry_lock.release()

def _journal_changed_receipt(self):
    """At turn end: the steward's newest journal entry gets one receipt
    (the strip's last journal receipt says whether it already has one)."""
    try:
        base = Path(self.dir)
        newest, newest_m = None, 0.0
        for rel in ("journal", ".ecgberht/journal"):
            d = base / rel
            if d.is_dir():
                for p in d.glob("*.md"):
                    m = p.stat().st_mtime
                    if m > newest_m:
                        newest, newest_m = p, m
        if newest is None:
            return
        if any(isinstance(r, dict) and r.get("entry_id") == newest.stem
               for r in self._read_strip().get("receipts") or []):
            return                                   # already receipted
        first = ""
        with io.open(newest, encoding="utf-8", errors="replace") as fh:
            for line in fh:
                if line.strip():
                    first = line.strip().lstrip("# ").strip()
                    break
        self._strip_receipt({"kind": "journal_update", "path": newest.relative_to(base).as_posix(),
                             "entry_id": newest.stem, "summary": first[:300] or newest.stem})
    except Exception:
        pass

def _account_policy_kwargs(self, family):
    if self.provider_connection["family"] == family and not self.provider_connection["native_default"]:
        import provider_native
        return {"env": provider_native.account_env(self.provider_connection)}
    return {}

def append_turns(campaign_dir, turns, *, thread_id: str | None = None) -> int:
    """Validate a complete batch, then append it with one lock/read/replace.

    Additional JSON fields on each turn are preserved. Matching IDs are skipped
    using append_turn's role/text semantics. Any invalid item or conflicting ID
    rejects the whole batch, never leaving a partially imported conversation.
    """
    if not isinstance(turns, (list, tuple)):
        raise ConversationHistoryError("invalid_turn_batch")
    prepared = []
    batch_ids = {}
    for item in turns:
        if (
            not isinstance(item, dict)
            or item.get("role") not in ("john", "steward")
            or not isinstance(item.get("text"), str)
            or ("at" in item and not isinstance(item["at"], str))
            or ("turn_id" in item and (not isinstance(item["turn_id"], str) or not item["turn_id"]))
        ):
            raise ConversationHistoryError("invalid_turn_batch")
        try:
            # Detach caller-owned nested metadata and reject non-JSON values
            # before creating history directories or acquiring the file lock.
            encoded = json.dumps(item, ensure_ascii=False, allow_nan=False)
            encoded.encode("utf-8")
            turn = json.loads(encoded)
        except (TypeError, ValueError, UnicodeError, RecursionError) as exc:
            raise ConversationHistoryError("history_encoding_failed") from exc
        turn.setdefault("at", datetime.now(timezone.utc).isoformat())
        identity = turn.get("turn_id")
        if identity is not None:
            previous = batch_ids.get(identity)
            if previous is not None:
                if (previous["role"], previous["text"]) != (turn["role"], turn["text"]):
                    raise ConversationHistoryError("turn_id_conflict")
                continue
            batch_ids[identity] = turn
        prepared.append(turn)
    with _THREAD_LOCK:
        target, lock = _paths(campaign_dir, thread_id, create=bool(prepared))
        if not prepared:
            return 0
        with _process_lock(lock):
            _check_path(target, directory=False)
            document = _read(target)
            existing_ids = {turn["turn_id"]: turn for turn in document["turns"] if "turn_id" in turn}
            additions = []
            for turn in prepared:
                previous = existing_ids.get(turn.get("turn_id"))
                if previous is not None:
                    if (previous["role"], previous["text"]) != (turn["role"], turn["text"]):
                        raise ConversationHistoryError("turn_id_conflict")
                    continue
                additions.append(turn)
            if not additions:
                return 0
            document["turns"].extend(additions)
            try:
                payload = (json.dumps(document, ensure_ascii=False, allow_nan=False, indent=2) + "\n").encode("utf-8")
            except (ValueError, UnicodeError, RecursionError) as exc:
                raise ConversationHistoryError("history_encoding_failed") from exc
            if len(payload) > MAX_HISTORY_BYTES:
                raise ConversationHistoryError("history_size_limit")
            _replace(target, payload)
            return len(additions)

def start(cdir, repo, brief, check="", engine_factory=None, steward=""):
    """Start a code job for the steward at ``cdir``: a worktree of ``repo`` and a coder engine given ``brief``.
    ``engine_factory(worktree) -> engine`` is the seam (steward_routes passes get_engine)."""
    brief = str(brief or "").strip()
    if not brief:
        return {"ok": False, "error": "a code job needs a brief"}
    root = _repo_root(repo or "")
    if root is None:
        return {"ok": False, "error": "not a git repository: %s" % repo}
    job_id = time.strftime("%Y%m%d-%H%M%S") + "-" + uuid.uuid4().hex[:6]
    branch = "steward-job-" + job_id
    wt = jobs_base() / job_id
    with _LOCK:      # the check, the worktree and the busy entry: one step, so two stewards never both start
        if _norm(root) in busy_repos():
            return {"ok": False, "error": "a code job is already running on %s; one writer at a time" % root}
        code, base, err = _git(root, "rev-parse", "HEAD")
        if code != 0:
            return {"ok": False, "error": "the repository has no commit to start from: %s" % err}
        code, _, err = _git(root, "worktree", "add", "-b", branch, str(wt), base, timeout=600)
        if code != 0:
            return {"ok": False, "error": "could not make the worktree: %s" % err[:300]}
        job = {"id": job_id, "repo": str(root), "branch": branch, "worktree": str(wt), "base": base, "brief": brief[:8000],
               "check": str(check or "")[:500], "status": "running", "started": time.strftime("%Y-%m-%d %H:%M:%S"),
               "steward_dir": str(cdir), "steward": steward}
        _write_job(cdir, job)
        b = _busy_read()
        b[_norm(root)] = {"job": job_id, "cdir": str(cdir)}
        _busy_write(b)
    # the coder's own folder record: one workbench terminal
    terms = Path(wt) / ".anchor" / "steward-terms.json"
    terms.parent.mkdir(parents=True, exist_ok=True)
    terms.write_text(json.dumps({"1": {"label": "code job " + job_id, "created": job["started"], "archived": False}}), encoding="utf-8")
    _exclude_local(wt)
    try:
        eng = engine_factory(str(wt)) if engine_factory else None
        if eng is None:
            raise RuntimeError("no engine slot for the coder")
        eng.code_job = {"cdir": str(cdir), "id": job_id, "repo": str(root)}
        eng.on_turn_done = lambda result: threading.Thread(target=finish, args=(cdir, job_id, result), name="code-job-" + job_id, daemon=True).start()
        ok, why = eng.wake(fresh=True, seed=coder_brief(job))
        if not ok:
            raise RuntimeError(why)
    except Exception as e:
        j = _transition(cdir, job_id, LIVE, status="failed", finished=time.strftime("%Y-%m-%d %H:%M:%S"), error="the coder could not start: %s" % e)
        _cleanup(j or job, keep_branch=False)
        return {"ok": False, "error": "the coder could not start: %s" % e, "job": job_id}
    return {"ok": True, "job": job_id, "branch": branch, "worktree": str(wt)}

def _finish(cdir, job_id, job, result):
    wt, repo = job["worktree"], job["repo"]
    summary = str((result or {}).get("text") or "")[-1500:]
    err = str((result or {}).get("error") or "")
    check_out, check_ok = "", None
    if job.get("check") and not err:
        try:
            r = subprocess.run(job["check"], cwd=wt, shell=True, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=CHECK_TIMEOUT_S)
            check_ok = r.returncode == 0
            check_out = ((r.stdout or "") + (r.stderr or ""))[-1200:]
        except Exception as e:
            check_ok, check_out = False, "the check did not run: %s" % e
    commit_err = ""
    files = []
    code, _, gerr = _git(wt, "add", "-A", timeout=600)
    if code != 0:
        commit_err = "git add failed: " + gerr[:250]
    if not commit_err:
        code, staged, gerr = _git(wt, "diff", "--cached", "--name-only", timeout=600)
        if code != 0:
            commit_err = "git diff failed: " + gerr[:250]
        elif staged:
            code, out, gerr = _git(wt, "commit", "-q", "-m", "Code job %s for the steward\n\n%s" % (job_id, job["brief"][:600]), timeout=600)
            if code != 0:
                commit_err = "git commit failed: " + (gerr or out)[:250]
    if not commit_err:
        # the change is what the branch holds beyond its base (the coder may have committed itself)
        code, names, gerr = _git(wt, "diff", "--name-only", job["base"], "HEAD", timeout=600)
        if code != 0:
            commit_err = "git diff failed: " + gerr[:250]
        else:
            files = [n for n in names.splitlines() if n.strip()]
    landed, land_note = False, ""
    if commit_err:
        land_note = "not landed: the commit failed (%s); the worktree is kept at %s" % (commit_err, wt)
    elif not files:
        land_note = "nothing changed"
    elif err:
        land_note = "not landed: the coder's turn ended in an error; the work waits on branch %s" % job["branch"]
    elif check_ok is False:
        land_note = "not landed: the check failed; the work waits on branch %s" % job["branch"]
    else:
        landed, land_note = land(job, files)
    done = _transition(cdir, job_id, ("finishing",), status="failed" if (err or commit_err) else "done",
                       finished=time.strftime("%Y-%m-%d %H:%M:%S"), summary=summary, error=err or commit_err,
                       check_ok=check_ok, check_output=check_out, files=files, landed=landed, land_note=land_note)
    if done is None:
        return
    if not commit_err:
        _cleanup(done, keep_branch=not (landed or not files))
    _report(cdir, done)

def _land_under_lock(job, _gs):
    repo, wt = job["repo"], job["worktree"]
    code, head, err = _git(repo, "rev-parse", "HEAD")
    if code != 0:
        return False, "not landed: could not read %s HEAD (%s)" % (repo, err[:120])
    code, out, err = _git(wt, "merge", "--no-edit", head, timeout=600)       # the job's own worktree: safe
    if code != 0:
        _git(wt, "merge", "--abort")
        return False, "not landed: the work conflicts with newer changes in %s; it waits on branch %s" % (repo, job["branch"])
    if job.get("check"):
        try:
            r = subprocess.run(job["check"], cwd=wt, shell=True, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=CHECK_TIMEOUT_S)
            if r.returncode != 0:
                return False, "not landed: the check failed after bringing in newer changes; the work waits on branch %s" % job["branch"]
        except Exception as e:
            return False, "not landed: the check could not run after integration (%s)" % e
    code, src, _ = _git(wt, "rev-parse", "HEAD")
    code2, names, _ = _git(wt, "diff", "--name-only", head, src)
    if code != 0 or code2 != 0:
        return False, "not landed: could not read the integrated change"
    land_files = [n for n in names.splitlines() if n.strip()]
    if not land_files:
        return False, "nothing changed beyond what %s already has" % repo
    return _gs.land_locked(repo, src, land_files, "Code job %s for the steward\n\n%s" % (job["id"], job["brief"][:600]),
                           who="code job " + job["id"], expect_head=head)

def stop(cdir, job_id=None, engine_lookup=None):
    """His "stop": kill the running job (the newest when no id); its work so far stays on its branch."""
    jobs = [j for j in read_jobs(cdir).values() if j.get("status") in LIVE and (not job_id or j["id"] == job_id)]
    if not jobs:
        return {"ok": False, "error": "no code job is running"}
    job = sorted(jobs, key=lambda j: j["started"])[-1]
    if job.get("status") == "finishing":
        if time.time() - float(job.get("finishing_at") or 0) < CHECK_TIMEOUT_S + 900:
            return {"ok": False, "error": "the code job is already finishing; its result is on the way"}
        _transition(cdir, job["id"], ("finishing",), status="failed", finished=time.strftime("%Y-%m-%d %H:%M:%S"),
                    error="the job's finish never completed", land_note="released by stop; the work waits on branch %s" % job["branch"])
        return {"ok": True, "job": job["id"], "branch": job["branch"], "released": True}
    stopped = _transition(cdir, job["id"], ("running",), status="stopped", finished=time.strftime("%Y-%m-%d %H:%M:%S"),
                          land_note="stopped by John; nothing landed; the work so far stays on branch %s" % job["branch"])
    if stopped is None:
        return {"ok": False, "error": "the code job is already finishing; its result is on the way"}
    try:
        eng = engine_lookup(job["worktree"]) if engine_lookup else None
        if eng is not None:
            eng.on_turn_done = None
            eng.stop()
    except Exception:
        pass
    try:
        _git(job["worktree"], "add", "-A")
        _git(job["worktree"], "commit", "-q", "-m", "Code job %s stopped by John (unfinished)" % job["id"])
        _git(job["repo"], "worktree", "remove", "--force", job["worktree"], timeout=300)
    except Exception:
        pass
    return {"ok": True, "job": job["id"], "branch": job["branch"]}

def _load_artifact(skill, names):
    directory = Path(skill['source'])
    role = skill.get('role')
    searches = [(content_root() / skill['id'], names), (directory, names)]
    if role:
        searches = [(content_root() / skill['id'], names),
                    (directory, tuple(name.replace('.json', '.' + role + '.json') for name in names)),
                    (directory / 'knowledge' / role, names)]
    for base, file_names in searches:
        for name in file_names:
            path = base / name
            if not path.is_file() or not _allowed(path):
                continue
            try:
                data = json.loads(_text(path))
                if not isinstance(data, (dict, list)):
                    raise ValueError('expected an object or array')
                return data, path, None
            except (ValueError, TypeError) as exc:
                return None, path, 'Unreadable content: ' + str(exc)
    return None, None, None

def _combined_display(skill, resources):
    """Foundry-owned foundry-skill-display/v1 handoff; canonical sources stay live.

    Snapshot HTML targets are never served as executable mockup pages. Anchors
    resolve the declared original file, check its frozen hash, and open in the
    same contained reader as ordinary Library resources.
    """
    data, path, error = _load_artifact(skill, ('maps.json',))
    if data is None:
        return None, [error] if error else []
    if not isinstance(data, dict) or data.get('schema') != 'foundry-skill-display/v1' or data.get('skill_id') != skill['id']:
        return None, ['Unsupported or different-skill maps.json handoff']
    for field in ('sources', 'anchors', 'resources'):
        if not isinstance(data.get(field), list):
            return None, [field + ' must be an array in maps.json']
    for field, child in (('knowledge', 'nodes'), ('process', 'steps'), ('process', 'edges')):
        if not isinstance(data.get(field), dict) or not isinstance(data[field].get(child), list):
            return None, [field + '.' + child + ' must be an array in maps.json']
    issues, links = [], {}
    sources = {s.get('id'): s for s in data.get('sources', []) if isinstance(s, dict)}
    for anchor in data.get('anchors', []):
        if not isinstance(anchor, dict):
            issues.append('Invalid source anchor')
            continue
        source = sources.get(anchor.get('source_id'), {})
        spec = {'path': source.get('origin'), 'line': anchor.get('start'), 'sha256': source.get('sha256')}
        link = _anchor_link(spec, skill, path.parent, resources)
        if link and link.get('href'):
            target = _path(source.get('origin'), Path(skill['source']), path.parent)
            start, end = anchor.get('start'), anchor.get('end')
            if isinstance(start, int) and isinstance(end, int) and 1 <= start <= end:
                excerpt = '\n'.join(_text(target).splitlines()[start - 1:end])
                if anchor.get('sha256') and hashlib.sha256(excerpt.encode()).hexdigest() != anchor['sha256']:
                    link['problem'] = 'Source changed: anchored excerpt differs'
            else:
                link['problem'] = 'Invalid source range'
        if not link:
            link = {'label': 'Source unavailable', 'problem': 'Missing original source'}
        if link.get('problem'):
            issues.append(link['problem'])
        links[anchor.get('id')] = link
    categories = {'Reusable material': 'material', 'References': 'references', 'Other skills': 'skills', 'Tools': 'tools'}
    for row in data.get('resources', []):
        if not isinstance(row, dict):
            issues.append('Invalid Library resource')
            continue
        link = links.get(row.get('anchor_id'), {})
        if not link.get('href'):
            issues.append('Library target missing: ' + str(row.get('id')))
            continue
        backing = next((r for r in resources if r['id'] == link.get('resourceId')), {})
        resources.append({**backing, 'id': row.get('id'), 'title': row.get('title'),
                          'category': categories.get(row.get('category'), 'material'),
                          'description': row.get('summary', ''), 'problem': link.get('problem'),
                          'frequency': _frequency(row, skill, path.parent), 'library': True})
    flow = data.get('process') if isinstance(data.get('process'), dict) else {}
    steps = []
    for row in flow.get('steps', []):
        if not isinstance(row, dict):
            issues.append('Invalid process step')
            continue
        aa = [links[a] for a in row.get('anchors', []) if a in links]
        steps.append({**row, 'description': row.get('summary'), 'anchorLinks': aa,
                      'codeLink': aa[0] if row.get('code_status') == 'anchored' and aa else
                          {'label': 'instructions-only', 'note': 'Session work; no code on this path.'},
                      'instructionLink': aa[-1] if row.get('instruction_status') == 'anchored' and aa else
                          {'label': 'no-separate-instruction', 'note': 'See the program source.'}})
        if not aa:
            issues.append('No process sources: ' + str(row.get('id')))
    knowledge = data.get('knowledge') if isinstance(data.get('knowledge'), dict) else {}
    nodes = [{**n, 'name': n.get('title'), 'parent': n.get('parent_id')}
             for n in knowledge.get('nodes', []) if isinstance(n, dict)]
    disagreements = [{**d, 'sourceLinks': [links[a] for a in d.get('anchors', []) if a in links]}
                     for d in flow.get('disagreements', []) if isinstance(d, dict)]
    return {'source': str(path), 'qualification': data.get('refinement') or 'Walkthrough awaiting human review.',
            'steps': steps, 'edges': [{**e, 'from': e.get('source'), 'to': e.get('target'),
                                      'sourceLink': links.get(e.get('anchor_id'))}
                                     for e in flow.get('edges', []) if isinstance(e, dict)],
            'exits': flow.get('terminals', []),
            'disagreements': disagreements, 'nodes': nodes, 'issues': issues}, issues

def _path(raw, directory, artifact_dir=None):
    if not raw or not isinstance(raw, str) or '\x00' in raw:
        return None
    raw = raw.replace('\\', '/')
    path = Path(raw)
    candidates = [path] if path.is_absolute() else [directory / path]
    if not path.is_absolute():
        if artifact_dir:
            candidates.append(artifact_dir / path)
        candidates.extend([Path(api.FOUNDRY_ROOT) / path, discovery_roots()[2] / path])
    return next((p.resolve() for p in candidates if p.is_file() and _allowed(p)
                 and p.suffix.lower() in TEXT_TYPES and not any(
                     part.startswith('.') for part in p.relative_to(p.anchor).parts
                     if part not in ('.agents', '.claude', '.codex'))), None)

def _allowed(path):
    roots = (*discovery_roots(), content_root())
    return any(_inside(path, root) for root in roots)

def select_model(family, catalog):
    if family not in FAMILIES:
        raise PolicyUnavailable(str(family), "unknown model family")
    rows = sorted(catalog, key=lambda item: item["rank"])
    if not rows:
        raise PolicyUnavailable(family, "no available model")
    if family == "chatgpt" and len(rows) > 1 and rows[0]["rank"] == rows[1]["rank"]:
        raise PolicyUnavailable(family, "latest model ranking is ambiguous; refresh subscription capabilities")
    chosen = rows[0]
    initial_model = chosen["model"]
    initial_evidence = chosen["evidence"]
    by_name = {row["model"]: row for row in rows}
    visited = set()
    while chosen.get("upgrade"):
        target = chosen["upgrade"]
        if isinstance(target, dict):
            target = target.get("model") or target.get("id")
        if target in visited:
            raise PolicyUnavailable(family, "cyclic catalog upgrade metadata")
        visited.add(chosen["model"])
        if target not in by_name:
            raise PolicyUnavailable(family, "recommended model upgrade is unavailable")
        chosen = by_name[target]
    try:
        effort = highest_effort(chosen["efforts"])
    except ValueError as error:
        raise PolicyUnavailable(family, str(error), code="unsupported_effort") from error
    result = {"policy_version": POLICY_VERSION, "requested_policy": dict(DEFAULT_POLICY),
              "family": family, "model": chosen["model"], "effort": effort,
              "selection_evidence": initial_evidence + ("+provider_upgrade" if initial_model != chosen["model"] else ""), "model_attested": False}
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:/-]{0,199}", result["model"]):
        raise PolicyUnavailable(family, "catalog model identity has unsupported characters")
    if initial_evidence == "provider_catalog_order":
        result["warning"] = "Provider-recommended catalog order; frontier ranking is not explicitly attested."
    return result

export function runCli(argv, io = {}) {
  const write = io.write ?? ((s) => process.stdout.write(s));
  const exit = io.exit ?? ((code) => process.exit(code));
  const result = main(argv);
  const exitCode = result && result.ok === true ? 0 : 1;
  write(`${JSON.stringify(result, null, 2)}\n`);
  exit(exitCode);
  return { result, exitCode };
}

export function main(argv) {
  const tokens = Array.isArray(argv) ? argv : [];

  if (!tokens.length) {
    return {
      ok: false,
      error: 'missing_verb',
      spelling: SPELLING,
      message: `${SPELLING} requires a closed verb. Pass one of the closed list.`,
      closed_verbs: [...CLOSED_VERBS],
    };
  }

  const parsed = parseRootsFromCliArgs(tokens);
  // Prefer first non-flag token as verb (supports `status --roots X` and `--roots X status`)
  let verb = null;
  let verbIndex = -1;
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    if (t === '--roots' || t === '-R' || t === '--project' || t === '-p') {
      // skip flag and its value
      if (tokens[i + 1] && !tokens[i + 1].startsWith('-')) i++;
      continue;
    }
    if (t.startsWith('--roots=') || t.startsWith('--project=')) continue;
    // Other long options are not the verb
    if (t.startsWith('--') || t.startsWith('-')) {
      // value-taking flags already handled for roots/project; skip known pairs generically
      if (
        tokens[i + 1] &&
        !tokens[i + 1].startsWith('-') &&
        !t.includes('=')
      ) {
        // only skip value when this looks like a flag that takes one (heuristic: not boolean)
        const booleanFlags = new Set(['--dry-run', '--no-persist']);
        if (!booleanFlags.has(t)) i++;
      }
      continue;
    }
    verb = t;
    verbIndex = i;
    break;
  }

  if (!verb) {
    return {
      ok: false,
      error: 'missing_verb',
      spelling: SPELLING,
      message: `${SPELLING} requires a closed verb. Pass one of the closed list.`,
      closed_verbs: [...CLOSED_VERBS],
      cli_roots: parsed.roots,
      cli_project: parsed.project,
    };
  }

  const args = tokens.filter((_, i) => i !== verbIndex);
  return runVerb(verb, args);
}

export function loadProjectSurfaces(projectPath) {
  const root = path.resolve(projectPath);
  const stripPath = path.join(root, STRIP_FILE_NAME);
  const facePath = path.join(root, FACE_FILE_NAME);

  const result = {
    ok: true,
    project_path: root,
    face_path: null,
    strip_path: null,
    strip_source: null,
    face: null,
    strip: null,
    face_loaded: false,
    errors: [],
  };

  if (fs.existsSync(stripPath) && fs.statSync(stripPath).isFile()) {
    try {
      const raw = fs.readFileSync(stripPath, 'utf8');
      const parsed = parseStrip(raw);
      if (parsed.ok) {
        result.strip = parsed.strip;
        result.strip_path = stripPath;
        result.strip_source = 'strip.json';
      } else {
        result.errors.push(parsed);
      }
    } catch (e) {
      result.errors.push({ error: 'strip_read_failed', message: String(e?.message ?? e) });
    }
  }

  if (fs.existsSync(facePath) && fs.statSync(facePath).isFile()) {
    try {
      const raw = fs.readFileSync(facePath, 'utf8');
      const face = parseFaceDocument(raw);
      if (face.ok) {
        result.face = face;
        result.face_path = facePath;
        result.face_loaded = true;
        if (!result.strip && face.strip_fence) {
          const parsed = parseStrip(face.strip_fence);
          if (parsed.ok) {
            result.strip = parsed.strip;
            result.strip_source = 'face_fence';
          }
        }
      }
    } catch (e) {
      result.errors.push({ error: 'face_read_failed', message: String(e?.message ?? e) });
    }
  }

  if (!result.strip && !result.face) {
    result.ok = false;
    result.error = 'no_face_or_strip';
  }

  return result;
}

export function verbUpdate(opts = {}) {
  const verb_name = opts.verb_name ?? 'update';
  const project_path = resolveProjectPath({
    project: opts.project,
    cwd: opts.cwd,
  });
  const surfaces = opts.surfaces ?? loadProjectSurfaces(project_path);
  const lifecycle = loadProjectRoadmap(project_path);
  const managed = lifecycle.ok && lifecycle.roadmap?.roadmap_events?.some(e=>e.kind==='refinement_update');
  if(managed && [opts.face_patch,opts.strip_tip,opts.strip_in_place_patch].some(p=>p &&
      (Object.hasOwn(p,'human_wait') || Object.hasOwn(p,'pending_request') || Object.hasOwn(p,'wait_ref')))) {
    return {ok:false,error:'managed-wait-event-owned',message:'Use refinement-update; a stamp cannot change managed human wait.'};
  }
  // W0 (2026-09-28): a wait's subject is a typed reference or 'none' — never free prose
  const wait_ref_in = opts.strip_tip && typeof opts.strip_tip === 'object' ? opts.strip_tip.wait_ref : undefined;
  if (wait_ref_in !== undefined && !isWaitRef(wait_ref_in)) {
    return { ok: false, error: 'bad_wait_ref', wait_ref: wait_ref_in, spelling: SPELLING, verb: verb_name, primary: 'update', project_path,
             message: '--wait-ref must be step:<id>, deliverable:<row>@<version>, decision:<id>, or none.' };
  }
  // W4 (2026-09-28): a repair act is a roadmap act and travels alone
  if (opts.repair_propose || opts.repair_resolve) {
    return repairAct(opts, project_path, lifecycle, verb_name);
  }

  if (!surfaces.strip && !surfaces.face) {
    return {
      ok: false,
      error: 'no_face_or_strip',
      spelling: SPELLING,
      verb: verb_name,
      primary: 'update',
      project_path,
      message: 'update/heartbeat needs Face or Strip',
    };
  }

  // W3 (2026-09-28): --horizon derives the line from the plan — the focus, then what follows it — and writes it as a
  // stamped instrument (the roadmap's last seq and the focus it derived from). A record whose stamp already covers
  // the last event with the same focus is unchanged: no write. The focus read is the strip's CURRENT one, so a focus
  // change he made is honoured, never overridden. Deterministic; no model.
  let horizon = null;
  if (opts.horizon) {
    const proj = lifecycle.ok && Array.isArray(lifecycle.roadmap?.roadmap_projection) ? lifecycle.roadmap.roadmap_projection : [];
    const evs = lifecycle.ok && Array.isArray(lifecycle.roadmap?.roadmap_events) ? lifecycle.roadmap.roadmap_events : [];
    const lastEv = evs.length ? evs[evs.length - 1] : null;
    const focusId = opts.current_step_id ?? surfaces.strip?.current_step_id ?? null;
    horizon = deriveHorizon({ projection: proj, current_step_id: focusId, n: 3, last_event: lastEv, reason: opts.horizon_reason });
    if (!horizon.ok) {
      return { ok: false, error: 'no_horizon', reason: horizon.reason, spelling: SPELLING, verb: verb_name, primary: 'update', project_path,
               message: `No horizon can be derived: ${horizon.reason}.` };
    }
    const lastSeq = lastEv && typeof lastEv.seq === 'number' ? lastEv.seq : 0;
    const stampedSeq = surfaces.strip?.horizon_source_seq;
    const whyOut = horizon.why ?? (surfaces.strip?.why_next ?? '');
    const otherFields = Object.keys(opts.strip_tip && typeof opts.strip_tip === 'object' ? opts.strip_tip : {}).length
      || Object.keys(opts.face_patch ?? {}).length || !!opts.current_step_id || !!opts.leave;
    // unchanged (no write) only when the stamp covers the last event with the same focus AND the line and why on
    // the strip already equal the derivation AND the call changes nothing else — a later edit of the line by
    // another update clears the stamp (below), so it can never freeze an old line (Grok W3)
    if (!opts.force && !otherFields && typeof stampedSeq === 'number' && stampedSeq >= lastSeq
        && surfaces.strip?.horizon_focus === horizon.focus
        && surfaces.strip?.next_recommended === horizon.line && String(surfaces.strip?.why_next ?? '') === String(whyOut)) {
      return { ok: true, unchanged: true, horizon, spelling: SPELLING, verb: verb_name, primary: 'update', project_path };
    }
    opts = { ...opts, strip_tip: { ...(opts.strip_tip && typeof opts.strip_tip === 'object' ? opts.strip_tip : {}),
      next_recommended: horizon.line, why_next: whyOut, horizon_source_seq: lastSeq, horizon_focus: horizon.focus, horizon_steps: horizon.steps } };
  } else if (opts.strip_tip && typeof opts.strip_tip === 'object'
             && (opts.strip_tip.next_recommended != null || opts.strip_tip.why_next != null || (opts.face_patch && opts.face_patch.why_next != null))) {
    // a line written by hand (the turn's, his) is not the derived one: the stamp clears so the next --horizon
    // re-derives rather than reporting "unchanged" over it
    opts = { ...opts, strip_tip: { ...opts.strip_tip, horizon_source_seq: null, horizon_focus: null } };
  }
  // the strip's next / why / wait are capped by words (the lead line must fit)
  const face_patch0 = opts.face_patch ?? {};
  const tip0 = opts.strip_tip && typeof opts.strip_tip === 'object' ? opts.strip_tip : {};
  for (const [field, value] of [['next_recommended', tip0.next_recommended], ['why_next', tip0.why_next ?? face_patch0.why_next],
                                ['human_wait', tip0.human_wait ?? face_patch0.human_wait]]) {
    const over = overCap(field, value);
    if (over) {
      return { ok: false, error: 'over_cap', ...over, spelling: SPELLING, verb: verb_name, primary: 'update', project_path,
               message: `${field} is ${over.words} words; the cap is ${over.cap}. Say it shorter.` };
    }
  }
  // --current-step pins the step that follows; a pin needs a next and a why
  const pin_id = typeof opts.current_step_id === 'string' && opts.current_step_id.trim() ? opts.current_step_id.trim() : null;
  let pin_steps = null;
  if (pin_id) {
    pin_steps = lifecycle.ok && Array.isArray(lifecycle.roadmap?.roadmap_projection) ? lifecycle.roadmap.roadmap_projection : [];
    if (!pin_steps.some((st) => st && st.id === pin_id)) {
      return { ok: false, error: 'unknown_step', step_id: pin_id, spelling: SPELLING, verb: verb_name, primary: 'update', project_path,
               message: `--current-step ${pin_id}: no such step in the roadmap.` };
    }
    const missing = missingSpine(surfaces.strip, { next_recommended: tip0.next_recommended, why_next: tip0.why_next ?? face_patch0.why_next });
    if (missing.length) {
      return { ok: false, error: 'spine_required', missing, spelling: SPELLING, verb: verb_name, primary: 'update', project_path,
               message: 'A pin needs a next and a why: pass --next-recommended and --strip-why-next (or have them on the strip).' };
    }
  }

  const prior_as_of = surfaces.strip?.as_of ?? null;
  const prior_instruments = Array.isArray(surfaces.strip?.instruments)
    ? surfaces.strip.instruments.map((e) => ({ ...e }))
    : [];
  const prior_receipts = Array.isArray(surfaces.strip?.receipts)
    ? surfaces.strip.receipts.map((e) => ({ ...e }))
    : [];
  const prior_instruments_len = prior_instruments.length;
  const prior_receipts_len = prior_receipts.length;

  // Reject any attempt to silently rewrite Strip clocks in place
  if (opts.strip_in_place_patch && Object.keys(opts.strip_in_place_patch).length) {
    const rejected = mutateStripInPlace(surfaces.strip, opts.strip_in_place_patch);
    return {
      ...rejected,
      spelling: SPELLING,
      verb: verb_name,
      primary: 'update',
      project_path,
    };
  }

  const face_patch = opts.face_patch ?? {};
  const face_result =
    Object.keys(face_patch).length > 0
      ? rewriteFaceNarrative(surfaces.face?.narrative ?? {}, face_patch)
      : {
          ok: true,
          authority: 'face_human_narrative',
          narrative: surfaces.face?.narrative ?? {},
          rewritten: [],
        };

  let strip = surfaces.strip ? { ...surfaces.strip } : null;
  let strip_append = null;
  let receipt_append = null;

  // W0: a bare `--leave` records where he left and moves no clock — no instrument, one receipt
  const leave_only = !!opts.leave && !Object.keys(face_patch).length && !pin_id
    && !(opts.strip_tip && typeof opts.strip_tip === 'object' && Object.keys(opts.strip_tip).length);
  if (strip && opts.leave) {
    const events = lifecycle.ok && Array.isArray(lifecycle.roadmap?.roadmap_events) ? lifecycle.roadmap.roadmap_events : [];
    const last = events.length ? events[events.length - 1] : null;
    // the deliverable version he was on: copied ONLY when the last event already carries one (a refinement
    // event's presentation), never invented (Grok W0)
    const op = last && last.kind === 'refinement_update' && last.operation && typeof last.operation === 'object' ? last.operation : null;
    const presentation = op ? (op.presentation_id ?? op.base_presentation_id ?? null) : null;
    const receipt = {
      schema: RECEIPT_SCHEMA_ID,
      kind: 'leave',
      as_of: opts.as_of ?? todayIso(),
      at: typeof opts.leave_at === 'string' && opts.leave_at.trim() ? opts.leave_at.trim() : new Date().toISOString(),
      current_step_id: strip.current_step_id ?? null,
      last_event_seq: last?.seq ?? null,
      last_event_at: last?.at ?? null,
      last_event_kind: last?.kind ?? null,
      last_event_step_id: last?.step_id ?? op?.step_id ?? null,
      presentation_id: presentation,
      active_effort: strip.active_effort ?? null,
      wait_ref: strip.wait_ref ?? null,
      human_wait: strip.human_wait ?? 'none',
    };
    const rec = appendStripReceipt(strip, receipt, { apply_to_projection: false });
    if (!rec.ok) {
      return { ok: false, error: rec.error, spelling: SPELLING, verb: verb_name, primary: 'update', message: 'Leave receipt append failed' };
    }
    strip = rec.strip;
    receipt_append = receipt;
  }

  if (strip && !leave_only) {
    const instrument = {
      _kind: 'instrument',
      kind: verb_name === 'heartbeat' ? 'heartbeat' : (horizon ? 'horizon' : 'update'),
      as_of: opts.as_of ?? todayIso(),
      source: horizon ? 'verb_update:horizon' : 'verb_update',
      ...(horizon ? { derived: true } : {}),
      ...(opts.strip_tip && typeof opts.strip_tip === 'object' ? opts.strip_tip : {}),
    };
    // Map face active_effort / human_wait into strip tip when provided
    if (face_patch.active_effort != null) instrument.active_effort = face_patch.active_effort;
    if (face_patch.human_wait != null) instrument.human_wait = face_patch.human_wait;
    if (face_patch.why_next != null && instrument.why_next == null) {
      instrument.why_next = face_patch.why_next;
    }
    if (pin_id) instrument.current_step_id = pin_id;

    const appended = appendStripInstrument(strip, instrument, { apply_to_projection: true });
    if (!appended.ok) {
      return {
        ok: false,
        error: appended.error,
        spelling: SPELLING,
        verb: verb_name,
        primary: 'update',
        message: 'Strip instrument append failed',
      };
    }
    strip = appended.strip;
    strip_append = instrument;

    // Heartbeat also leaves a structured receipt
    if (verb_name === 'heartbeat' || opts.append_receipt) {
      const receipt = {
        schema: RECEIPT_SCHEMA_ID,
        kind: 'heartbeat',
        as_of: instrument.as_of,
        active_effort: strip.active_effort ?? null,
        why_next: strip.why_next ?? null,
        human_wait: strip.human_wait ?? 'none',
        uncertainty_flags: Array.isArray(strip.uncertainty_flags)
          ? [...strip.uncertainty_flags]
          : [],
      };
      const rec = appendStripReceipt(strip, receipt, { apply_to_projection: false });
      if (rec.ok) {
        strip = rec.strip;
        receipt_append = receipt;
      }
    }
  }

  // Prove prior history clocks were not rewritten: prior entries deep-equal prefix
  const history_intact =
    !strip ||
    (Array.isArray(strip.instruments) &&
      prior_instruments.every((e, i) => stableEqual(strip.instruments[i], e)) &&
      prior_receipts.every((e, i) => stableEqual(strip.receipts[i], e)));

  const persist = opts.persist !== false && !opts.dry_run;
  const written = { face: false, strip: false };
  if (persist && !opts.surfaces) {
    if (face_result.rewritten.length && surfaces.face_path) {
      writeFaceNarrative(surfaces.face_path, face_result.narrative, surfaces.face?.raw);
      written.face = true;
    } else if (face_result.rewritten.length) {
      const facePath = path.join(project_path, FACE_FILE_NAME);
      writeFaceNarrative(facePath, face_result.narrative, surfaces.face?.raw);
      written.face = true;
    }
    if (strip && surfaces.strip_source === 'strip.json') {
      const stripPath = surfaces.strip_path ?? path.join(project_path, STRIP_FILE_NAME);
      // Atomic: this is the append-only receipt ledger, and the bridge caller
      // can be KILLED on timeout — a truncated write here loses receipts.
      writeFileAtomicSync(stripPath, `${JSON.stringify(strip, null, 2)}\n`);
      written.strip = true;
    }
    // the same call pins the roadmap: navigation.current on the step that follows, off the rest
    if (pin_id) {
      written.pinned = pin_id;
      written.unpinned = [];
      // a step without a course navigation is pinned by the strip alone (the reader's current_step_id comes first)
      for (const st of pin_steps) {
        const nav = st.navigation && typeof st.navigation === 'object' ? st.navigation : null;
        const isTarget = st.id === pin_id;
        if (!nav) continue;
        if (!isTarget && nav.current !== true) continue;
        if (isTarget && nav.current === true) continue;
        const res = appendRoadmapEventThroughSpine(project_path,
          { kind: 'step_set', step_id: st.id, fields: { navigation: { ...nav, current: isTarget } } }, { skip_index: true });
        if (!res.ok) return { ...res, verb: verb_name, primary: 'update', project_path, pinned: false };
        if (!isTarget) written.unpinned.push(st.id);
      }
    }
    // TW2 precompute hook: brief cache is a declared projection (zero write
    // authority) refreshed at update/heartbeat time so the packet opens with
    // zero further gathering. Opt-in via --precompute-brief.
    if (opts.precompute_brief) {
      precomputeBriefCache(project_path);
      written.brief_cache = true;
    }
  }

  return {
    ok: true,
    spelling: SPELLING,
    verb: verb_name,
    primary: 'update',
    project_path,
    authority: {
      face: 'human_narrative_rewrite',
      strip: 'append_only',
    },
    face: face_result,
    strip,
    strip_append,
    receipt_append,
    prior_as_of,
    prior_instruments_length: prior_instruments_len,
    prior_receipts_length: prior_receipts_len,
    instruments_length: strip?.instruments?.length ?? 0,
    receipts_length: strip?.receipts?.length ?? 0,
    history_intact,
    strip_history_rewritten: !history_intact,
    persisted: written,
    dry_run: Boolean(opts.dry_run) || opts.persist === false,
    message: 'Face narrative updated where patched; Strip history append-only',
  };
}

export function verbRoadmapSet(opts = {}) {
  const step_id = opts.step ?? null;
  if (!nonEmpty(step_id)) {
    return {
      ok: false,
      error: 'roadmap_set_requires_step',
      spelling: SPELLING,
      verb: 'roadmap-set',
      primary: 'roadmap-set',
      message: 'roadmap-set requires --step <id>.',
      required: ['step'],
    };
  }

  const { project_path, loaded } = resolveRoadmapSurfaces(opts);
  if (!loaded.ok) {
    return {
      ok: false,
      error: loaded.error ?? 'roadmap_read_failed',
      spelling: SPELLING,
      verb: 'roadmap-set',
      primary: 'roadmap-set',
      project_path,
      message: loaded.message ?? 'roadmap.json unreadable',
    };
  }
  if (!loaded.exists) {
    return {
      ok: false,
      error: 'no_roadmap',
      spelling: SPELLING,
      verb: 'roadmap-set',
      primary: 'roadmap-set',
      project_path,
      message:
        'No engine Roadmap for this project — nothing to set. Propose steps first (roadmap-propose); prose is not a step list.',
    };
  }

  let event;
  if (opts.status != null) {
    const receipt =
      opts.receipt && typeof opts.receipt === 'object'
        ? opts.receipt
        : { who: opts.who ?? null, when: opts.when ?? null, why: opts.reason ?? opts.why ?? null };
    if (!isValidFlipReceipt(receipt)) {
      return {
        ok: false,
        error: 'status_flip_requires_receipt',
        spelling: SPELLING,
        verb: 'roadmap-set',
        primary: 'roadmap-set',
        project_path,
        step_id,
        required: [...FLIP_RECEIPT_FIELDS],
        message:
          'Status flip refused without receipt: pass --who and --reason (who/why; when defaults to event date).',
        single_writer: ROADMAP_SINGLE_WRITER,
      };
    }
    if (opts.status === 'done') {
      // cockpit Wave B: the steward's close states the next act and the goal re-read first
      const demand = demandClose(project_path, loaded.roadmap, step_id, opts.goal_reread ?? null);
      if (!demand.ok) return { ...demand, spelling: SPELLING, verb: 'roadmap-set', primary: 'roadmap-set', project_path, step_id };
    }
    event = {
      kind: 'status_flip',
      step_id,
      from: opts.from ?? null,
      to: opts.status,
      receipt,
      at: opts.as_of ?? undefined,
      ...(opts.goal_reread ? { goal_reread: opts.goal_reread } : {}),
      ...(opts.client_event_id ? { client_event_id: opts.client_event_id } : {}),
    };
    if (event.from == null) delete event.from;
  } else if (nonEmpty(opts.commissioned_as)) {
    event = {
      kind: 'commission_bind',
      step_id,
      commissioned_as: opts.commissioned_as,
      at: opts.as_of ?? undefined,
      ...(opts.client_event_id ? { client_event_id: opts.client_event_id } : {}),
    };
  } else {
    const fields = {};
    if (opts.name != null) fields.name = opts.name;
    if (opts.done_when != null) fields.done_when = opts.done_when;
    if (opts.waiting_on != null) fields.waiting_on = opts.waiting_on;
    if (opts.due != null) fields.due = (opts.due === 'none' || opts.due === '') ? null : opts.due;
    for (const key of ['ref', 'tier', 'area']) {
      if (opts[key] != null) fields[key] = (opts[key] === 'none' || opts[key] === '') ? null : opts[key];
    }
    // the active set (2026-09-29): --active on|off · --active-order N|none · --pace YYYY-MM-DD|none
    if (opts.active != null) fields.active = !(opts.active === 'off' || opts.active === 'false' || opts.active === false);
    if (opts.active_order != null) fields.active_order = (opts.active_order === 'none' || opts.active_order === '') ? null : opts.active_order;
    if (opts.pace != null) fields.pace = (opts.pace === 'none' || opts.pace === '') ? null : opts.pace;
    // the seats (2026-09-30): --seat-in active|deck|none · --seat-order N|none (--seat alone is the model seat)
    if (opts.seat_in != null) fields.seat = (opts.seat_in === 'none' || opts.seat_in === '' || opts.seat_in === 'off') ? null : opts.seat_in;
    if (opts.seat_order != null) fields.seat_order = (opts.seat_order === 'none' || opts.seat_order === '') ? null : opts.seat_order;
    if (!Object.keys(fields).length) {
      return {
        ok: false,
        error: 'roadmap_set_requires_change',
        spelling: SPELLING,
        verb: 'roadmap-set',
        primary: 'roadmap-set',
        project_path,
        message:
          'roadmap-set needs a change: --status (+ --who/--reason), --commissioned-as, or --name/--done-when/--waiting-on/--due/--ref/--tier/--area/--active/--active-order/--pace.',
      };
    }
    event = {
      kind: 'step_set',
      step_id,
      fields,
      at: opts.as_of ?? undefined,
      ...(opts.client_event_id ? { client_event_id: opts.client_event_id } : {}),
    };
  }

  const persist = opts.persist !== false && !opts.dry_run && !loaded.injected;
  const written = { roadmap: false };
  let appended;

  if (persist) {
    // Wave 6 live-writer migration (roadmap.mjs:1139): production persist via spine.
    appended = appendRoadmapEventDurable(project_path, loaded.roadmap, event, {
      project_id: opts.project_id ?? loaded.roadmap?.project_id ?? null,
      home: opts.home,
      paths: opts.paths,
      env: opts.env,
      at: opts.as_of,
      skip_index: !opts.project_id && !opts.home,
    });
    if (!appended.ok) {
      return {
        ...appended,
        verb: 'roadmap-set',
        primary: 'roadmap-set',
        project_path,
      };
    }
    written.roadmap = appended.sot_written === true || appended.persisted === true;
  } else {
    appended = appendRoadmapEvent(loaded.roadmap, event);
    if (!appended.ok) {
      return {
        ...appended,
        verb: 'roadmap-set',
        primary: 'roadmap-set',
        project_path,
      };
    }
  }

  return {
    ok: true,
    spelling: SPELLING,
    verb: 'roadmap-set',
    primary: 'roadmap-set',
    project_path,
    event: appended.event,
    roadmap: appended.roadmap,
    projection: appended.projection,
    step_id,
    events_only: true,
    projection_written_directly: false,
    single_writer: ROADMAP_SINGLE_WRITER,
    persisted: written,
    dry_run: Boolean(opts.dry_run) || opts.persist === false,
    spine: persist ? true : undefined,
    message: `Roadmap event '${appended.event.kind}' appended for step '${step_id}' (events only; projection derived).`,
  };
}

export function appendRoadmapEventThroughSpine(projectPath, event, opts = {}) {
  const storeGate = assertStoreDeclared('roadmap_events');
  if (!storeGate.ok) return storeGate;

  if (!event || typeof event !== 'object' || Array.isArray(event)) {
    return spineFailure(SPINE_CODE.STATE_UNKNOWN, { error: 'event_not_object' });
  }

  // Kind gate: keep SPINE_KIND_REFUSED + allow-list text, but preserve the pure
  // law's error identity (`unknown_roadmap_event_kind`) so durable callers
  // (appendRoadmapEventDurable / single-writer law) still see the authority
  // refusal they always refused — Wave 6 must not rename pure-law refusals.
  const kindGate = assertEventKindAllowed(event.kind);
  if (!kindGate.ok) {
    return {
      ...kindGate,
      error: 'unknown_roadmap_event_kind',
      event_kinds: [...SPINE_EVENT_KINDS],
    };
  }

  const root = path.resolve(projectPath);
  const ledgerPath = roadmapLedgerPath(root);
  const flushIndex = shouldFlushPortfolioIndex(opts);

  const timeoutMs = opts.timeoutMs ?? LOCK_TIMEOUT_MS;

  let lockedResult;
  try {
    lockedResult = withFileLock(
      ledgerPath,
      () => {
        // LOAD under the lock (whole-file RMW serialisation). Always prefer the
        // on-disk ledger when present so concurrent OS processes serialise
        // correctly; seed is only used to initialise a missing file.
        const loaded = loadProjectRoadmap(root);
        if (!loaded.ok && loaded.exists) {
          return spineFailure(SPINE_CODE.LEDGER_UNREADABLE, {
            error: 'backing-store-unreadable',
            detail: loaded.message ?? loaded.error,
          });
        }
        let base;
        if (loaded.exists) {
          base = loaded.roadmap;
        } else if (opts.seed != null && opts.seed !== undefined) {
          base = opts.seed;
        } else {
          base = emptyRoadmap(opts.project_id ?? null);
        }

        if (event.kind === 'refinement_update') {
          const prior = findEventByClientId(base,event.client_event_id);
          if (!prior) {
            if (event.operation?.expected_seq !== base.roadmap_events.length) return {ok:false,error:'sequence-conflict',expected_seq:event.operation?.expected_seq,actual_seq:base.roadmap_events.length};
            const prepared=prepareRefinementEvent(root,base,event);
            if(!prepared.ok) return prepared;
            event=prepared.event;
          }
        } else if (event.kind === 'status_flip' && event.to === 'done' && foldRefinements(base.roadmap_events).slices?.[event.step_id]) {
          return {ok:false,error:'managed-slice-requires-explicit-close'};
        }
        let law = appendRoadmapEventSpineLaw(base, event, { at: opts.at });
        if (!law.ok) return law;
        // an accepted close that carries its goal re-read gets its goal_flip from the one writer
        const closing = closeOf(event, base);
        let goalFlip = null;
        if (closing && GOAL_REREAD.includes(closing.goal_reread) && !law.idempotent) {
          let face = '';
          try { face = fs.readFileSync(path.join(root, FACE_FILE_NAME), 'utf8'); } catch { face = ''; }
          goalFlip = {
            kind: 'goal_flip', step_id: closing.step_id, verdict: closing.goal_reread,
            goal_revision: northStarRevision(face), scope: closing.step_id,
            receipt: { who: event.receipt?.who ?? event.operation?.human?.who ?? 'steward', why: 'close of ' + closing.step_id },
            ...(opts.at ? { at: opts.at } : {}),
          };
          const flipLaw = appendRoadmapEventSpineLaw(law.roadmap, goalFlip, { at: opts.at });
          if (!flipLaw.ok) return flipLaw;
          law = { ...law, roadmap: flipLaw.roadmap, projection: flipLaw.projection, goal_flip: flipLaw.event };
        }
        if (law.idempotent) {
          const publication=event.kind==='refinement_update' ? publishRefinementProjections(root,law.roadmap) : null;
          if(publication && !publication.ok) return {...publication,committed:true,operation_id:event.client_event_id};
          return {
            ...law,
            projection_status:publication,
            project_path: root,
            roadmap_path: ledgerPath,
            persisted: false,
            sot_written: false,
            locked: true,
          };
        }

        // Persist under the same lock
        fs.mkdirSync(root, { recursive: true });
        writeFileAtomicSync(ledgerPath, projectRoadmapBytes(law.roadmap));
        let publication=null;
        if(event.kind==='refinement_update') {
          try { publication=publishRefinementProjections(root,law.roadmap); }
          catch(e) { return {ok:false,error:'projection-lag',committed:true,operation_id:event.client_event_id,detail:e.message}; }
          if(!publication.ok) return {...publication,committed:true,operation_id:event.client_event_id};
        }

        let carrier = null;
        let carrierRel = null;
        let carrierBytes = null;
        if (flushIndex) {
          carrier = roadmapEventCarrierRecord(law.roadmap, law.event, opts);
          carrierRel = relPathFor(CLASS.ROADMAP_EVENT, carrier.event_id);
          carrierBytes = roadmapEventBytes(carrier);
          const carrierAbs = path.join(root, ...carrierRel.split('/'));
          fs.mkdirSync(path.dirname(carrierAbs), { recursive: true });
          writeFileAtomicSync(carrierAbs, carrierBytes);
        }

        return {
          ok: true,
          projection_status:publication,
          spelling: law.spelling,
          authority: law.authority,
          event: law.event,
          roadmap: law.roadmap,
          projection: law.projection,
          issues: law.issues,
          events_only: true,
          spine: true,
          idempotent: false,
          seq: law.event.seq,
          client_event_id: law.event.client_event_id ?? null,
          project_path: root,
          roadmap_path: ledgerPath,
          persisted: true,
          sot_written: true,
          locked: true,
          single_writer: SPINE_SINGLE_WRITER,
          carrier,
          carrier_rel: carrierRel,
          carrier_bytes: carrierBytes,
          container_bytes: projectRoadmapBytes(law.roadmap),
        };
      },
      {
        timeoutMs,
        onTimeout: (info) => {
          const err = new Error(SPINE_TEXT[SPINE_CODE.LOCK_TIMEOUT]);
          err.code = SPINE_CODE.LOCK_TIMEOUT;
          err.spine_info = info;
          return err;
        },
      },
    );
  } catch (e) {
    if (e && e.code === SPINE_CODE.LOCK_TIMEOUT) {
      return spineFailure(SPINE_CODE.LOCK_TIMEOUT, {
        error: 'lock-contended',
      });
    }
    if (e && e.code === 'ELOCKTIMEOUT') {
      return spineFailure(SPINE_CODE.LOCK_TIMEOUT, {
        error: 'lock-contended',
      });
    }
    return spineFailure(SPINE_CODE.STATE_UNKNOWN, {
      error: 'unknown',
      detail: String(e?.message ?? e),
    });
  }

  if (!lockedResult || !lockedResult.ok) return lockedResult;
  if (lockedResult.idempotent) return lockedResult;

  // Optional portfolio index flush OUTSIDE the roadmap lock (lock-order law:
  // never hold project + portfolio locks together). Carrier bytes were written
  // under the roadmap lock; ingestWrite re-writes the carrier (idempotent
  // atomic replace) and flushes the derived row. Only minted project_ids index.
  if (flushIndex && lockedResult.carrier && lockedResult.carrier_rel) {
    const containerBytes = lockedResult.container_bytes;
    let ingest;
    try {
      ingest = ingestWrite({
        class: CLASS.ROADMAP_EVENT,
        project_id: opts.project_id,
        root,
        rel: lockedResult.carrier_rel,
        bytes: lockedResult.carrier_bytes,
        intent_paths: [pathEntryFor(ROADMAP_FILE_NAME, containerBytes)],
        home: opts.home,
        paths: opts.paths,
        env: opts.env,
        appendOpts: opts.appendOpts,
        beforeFlush: opts.beforeFlush,
        // Carrier already durable under the spine lock; re-assert atomically.
        write: (target) => {
          fs.mkdirSync(path.dirname(target.abs), { recursive: true });
          writeFileAtomicSync(target.abs, target.bytes.toString('utf8'));
        },
      });
    } catch (e) {
      // SoT already stands; never throw past the durable path.
      return {
        ...lockedResult,
        ok: true,
        indexed: false,
        sot_written: true,
        index_error: e?.code ?? 'ingest_threw',
        message:
          `Spine append seq=${lockedResult.seq} durable; index flush refused: ${e?.message ?? e}`,
      };
    }

    return {
      ...lockedResult,
      ok: ingest.ok === true,
      code: ingest.code ?? null,
      status: ingest.status ?? null,
      text: ingest.text ?? '',
      ingest,
      indexed: ingest.ok === true,
      row: ingest.row ?? null,
      seq_indexed: ingest.seq ?? null,
      intent: ingest.intent ?? null,
      intent_seq: ingest.intent_seq ?? null,
      intent_emitted: ingest.intent_emitted === true,
      freshness: ingest.freshness,
      path: ingest.path ?? null,
      trace: ingest.trace ?? [],
      // SoT stands even when index fails
      sot_written: true,
      message:
        ingest.ok === true
          ? `Spine append seq=${lockedResult.seq} durable + indexed.`
          : `Spine append seq=${lockedResult.seq} durable; index flush: ${ingest.text || ingest.code}`,
    };
  }

  return {
    ...lockedResult,
    indexed: false,
    message: `Spine append seq=${lockedResult.seq} durable under ${SPINE_LOCK_HELPER}+${SPINE_ATOMIC_WRITE}.`,
  };
}

export function demandClose(root, base, step_id, goal_reread) {
  const closing = closeOf({ kind: 'status_flip', to: 'done', step_id, goal_reread }, base);
  if (!closing) return { ok: true, demanded: false };
  const demand = demandSpineForClose(root, base, step_id);
  if (!demand.ok) return demand;
  if (!GOAL_REREAD.includes(goal_reread)) {
    return {
      ok: false, error: 'goal_reread_required', closing: step_id,
      message: 'Close refused: re-read the North Star and say so - --goal-reread reaffirmed|rewritten '
        + '(or goal_reread on the refinement close operation); the engine records the goal_flip.',
    };
  }
  return { ok: true, demanded: true };
}

export function suggestDepthFromStrip(stripOrSignals, opts = {}) {
  const signals = extractDispatchSignals(stripOrSignals);
  const result = lookupDispatch(signals, opts);
  const uncertainty_flags = [...signals.uncertainty_flags];
  if (
    result.flags.capacity_unknown &&
    !uncertainty_flags.includes('capacity_unknown')
  ) {
    uncertainty_flags.push('capacity_unknown');
  }
  if (result.flags.lite_bias && !uncertainty_flags.includes('LITE_bias')) {
    uncertainty_flags.push('LITE_bias');
  }

  return {
    ...result,
    signals,
    uncertainty_flags,
    capacity: signals.capacity,
  };
}

export function resolveSeats(opts = {}) {
  const prefs = loadAnchorPrefs(opts);
  const coding_driver = familyToSubscriptionDriver(prefs.coding_family);
  const review_driver = familyToSubscriptionDriver(prefs.review_family);

  const seat = {
    coding_family: prefs.coding_family,
    review_family: prefs.review_family,
    default_cli: prefs.default_cli,
    coding_driver,
    review_driver,
    /** Honest stamp: false when same-family; true when families differ. */
    cross_model: prefs.coding_family !== prefs.review_family,
    prefs_source: prefs.source,
    subscription_only: true,
    /** Production seats never use raw xAI HTTP + API key. */
    xai_http_seat: false,
    xai_api_key_path: false,
    product_model_ids: [],
    drivers: {
      coding: coding_driver,
      review: review_driver,
    },
  };

  // Fail closed if a driver is missing or not a subscription CLI
  const drivers = [coding_driver, review_driver];
  for (const d of drivers) {
    if (!d || !PRODUCTION_SEAT_DRIVERS.includes(d)) {
      seat.ok = false;
      seat.error = 'non_subscription_driver';
      seat.message = `Seat driver must be subscription CLI only; got ${d}`;
      return seat;
    }
  }

  // Raw HTTP grok driver name is forbidden for production seats
  if (coding_driver === 'grok' || review_driver === 'grok') {
    seat.ok = false;
    seat.error = 'xai_http_seat_forbidden';
    seat.message =
      'Production seats must use grok-cli subscription transport, not raw grok HTTP';
    return seat;
  }

  const productHits = findProductModelIds(seat);
  if (productHits.length) {
    seat.ok = false;
    seat.error = 'product_model_id_forbidden';
    seat.message = `Seat stamp must not carry product model IDs: ${productHits.join(', ')}`;
    seat.product_model_ids = productHits;
    return seat;
  }

  seat.ok = true;
  return seat;
}

export function routeUtterance(text, ctx = {}) {
  const trimmed = String(text ?? '').trim();
  if (!trimmed) return { lane: 'refuse', reason: 'empty_utterance' };

  if (wordCount(trimmed) <= ACT_MAX_WORDS) {
    // A SHORT utterance is command-shaped, so the destructive guard belongs here:
    // "delete all projects" must never compile to a verb.
    if (matchesDestructive(trimmed)) {
      return { lane: 'refuse', reason: 'destructive_free_form' };
    }
    const compiled = compileUtterance(trimmed, ctx);
    if (compiled.compiled) return { lane: 'act', compiled };
  } else {
    // A Campaign verb (High Seat W5) is command-shaped from its first word — "add a part to MBA Teaching: retool
    // homework 2 due Oct 27" runs past eight words — so it compiles at any length; compileUtterance runs the
    // destructive guard first, and the act writes nothing here: Anchor's Campaign writer applies it.
    const compiled = compileUtterance(trimmed, ctx);
    if (compiled.compiled && CAMPAIGN_ACT_IDS.includes(compiled.act)) return { lane: 'act', compiled };
  }

  // WHY THE DESTRUCTIVE GUARD DOES NOT RUN ON THE CONVERSE LANE (found in the
  // 2026-08-04 multi-turn smoke). John's real refinement was "...and DROP the separate
  // 'lock the decisions' stage, fold those decisions into the syllabus stage" —
  // DESTRUCTIVE_PATTERNS contains /\bdrop\b/, so the steward answered "Ecgberht will
  // not compile destructive free-form talk" to an ordinary editorial instruction. He
  // will say drop / remove / get rid of constantly while shaping a scaffolding.
  //
  // The guard's threat model is "free-form talk must never compile to a DESTRUCTIVE
  // VERB". On this lane nothing executes: the seat runs read-only (SEAT_ALLOWED_TOOLS),
  // the model has no write authority, and every proposal still needs a human
  // hash-bound confirm. So there is nothing here for the guard to protect, and applying
  // it anyway breaks the conversation it was meant to make safe.
  return { lane: 'converse' };
}

export function loadStewardContext(projectPath) {
  const surfaces = loadProjectSurfaces(projectPath);
  const loaded = loadProjectRoadmap(projectPath);
  const roadmap = loaded.exists && loaded.ok ? loaded.roadmap : null;
  const kickoff = roadmap ? projectKickoff(roadmap) : {
    ok: true,
    confirmed: null,
    open: null,
  };
  if (!kickoff.ok) {
    return {
      ok: false,
      code: CONVERSE_CODE.KICKOFF_CORRUPT,
      kickoff_check: kickoff,
    };
  }

  // Gate 5 / Wave 3: the store (<folder>/.ecgberht/kickoff/events.jsonl) is the lineage
  // of record for the kickoff conversation. A fresh session paints its latest OPEN
  // version from the store alone; the roadmap-ledger projection is the pre-Gate-5 lane
  // beside it. A store that cannot be read is reported by its own named row, never
  // guessed around.
  const store = readKickoffLineage(surfaces.project_path);
  if (!store.ok) {
    return { ok: false, code: store.code, store_check: store };
  }

  // loadProjectSurfaces returns the PARSED Face document ({ok, narrative, raw,
  // strip_fence}), so the narrative is read straight off it.
  const narrative = surfaces.face?.narrative ?? null;

  const projection = Array.isArray(roadmap?.roadmap_projection)
    ? roadmap.roadmap_projection : [];

  // THE STEP IN HAND, AND WHAT IT STILL NEEDS.
  //
  // This is what makes the steward walk alongside rather than hand over a document.
  // John: "I don't want to have to scaffold it all and go do the detail stuff later —
  // I could if I want to, but I don't have to." So detail is not demanded up front; it
  // is asked for one step at a time, when that step becomes the work.
  //
  // All three calls are PURE reads — no probe is written just because he opened the
  // chamber. The steward asks in its own voice, in the conversation; answers land as
  // typed elaboration events only when he actually answers.
  const active = findActiveStep(projection);
  let stepGaps = [];
  if (active && roadmap) {
    const detail = reconstructStepDetail(roadmap, active.step_id ?? active.id);
    if (detail && detail.ok !== false) {
      const predicate = evaluateCommissionability(detail);
      if (!predicate.ready) stepGaps = deriveTargetedQuestions(predicate, detail);
    }
  }

  // LIVE COMMISSIONED RUNS (2026-08-06, from John's day-one use). The seat could
  // not see run state, so it DISAVOWED a genuinely running Gandalf ("your Go
  // never reached the machinery") one turn after the machinery confirmed it.
  // The host's run records are the truth; read them so "is it running?" gets a
  // real answer. Read-only, best-effort, never authoritative for the roadmap.
  const commission_runs = readCommissionRuns(surfaces.project_path);

  // The step findings ledger — what runs and reflection have FED each step
  // (2026-08-07). Read for context; never authoritative for status.
  const findings = readStepFindings(surfaces.project_path);
  const step_findings = findings.ok ? findings.steps : {};

  // The DURABLE conversation — how the plan got where it is, in his words and the
  // steward's. Read for RECALL only; project state above still comes from the Face,
  // roadmap and Strip, and the ledger always wins (see conversation-log.mjs).
  const history = readConversationLog(surfaces.project_path, { limit: 20 });

  return {
    ok: true,
    project_path: surfaces.project_path,
    narrative,
    strip: surfaces.strip ?? null,
    roadmap,
    projection,
    active_step: active,
    step_gaps: stepGaps,
    confirmed_kickoff: store.confirmed ?? kickoff.confirmed,
    open_kickoff: store.open ?? kickoff.open,
    open_proposal: store.open ?? kickoff.open
      ?? (roadmap ? findOpenScaffoldProposal(roadmap) : null),
    kickoff_store: {
      state: store.state,
      next_version: store.next_version,
      prior_confirmed_hash: store.prior_confirmed_hash,
      proposal_count: store.proposal_count,
      receipt_count: store.receipt_count,
    },
    commission_runs,
    step_findings,
    history: history.ok ? history.turns : [],
    history_unreadable: history.ok ? false : true,
  };
}

export function buildStewardPrompt(context = {}, utterance = '', opts = {}) {
  const instruction = opts.planning ? STEWARD_PLAN_INSTRUCTION : STEWARD_TALK_INSTRUCTION;
  const lines = [instruction];
  lines.push('Discovery is adaptive: ask one consequential question at a time with context, why it matters, '
    + 'a recommendation and what its answer authorizes. Carry earlier answers forward from durable history. '
    + 'Usually three or four questions suffice; do not enforce a quota, a two-turn cutoff, or repeat known answers. '
    + 'Clarify shared versus group-specific deliverables, independent acceptance and essential prerequisites when relevant. '
    + 'Frame the plan when the intent is clear enough, retaining reversible assumptions and unresolved later choices.');
  // Gate 5 / Wave 3: on a THIN turn (turn >= KICKOFF_THIN_PROPOSAL_BY_TURN of a sparse
  // opening, nothing open or confirmed) the planning tier owes the smallest honest bundle.
  // Deliberately CONDITIONAL, like every other block: no thin turn -> no block -> every
  // recorded prompt stays byte-identical.
  if (opts.planning && opts.thin_turn) lines.push('', thinBundleInstruction(opts.thin_turn));
  lines.push('', '--- CAMPAIGN CONTEXT ---');

  const n = context.narrative ?? {};
  lines.push(`North star: ${nonEmptyOr(n.north_star, '(not set)')}`);
  lines.push(`Active effort: ${nonEmptyOr(n.active_effort, '(none)')}`);
  if (nonEmptyOr(n.human_wait, '')) lines.push(`Waiting on John: ${n.human_wait}`);

  const projection = Array.isArray(context.projection) ? context.projection : [];
  const stepFindings = context.step_findings ?? {};
  if (projection.length) {
    lines.push('', 'Confirmed roadmap steps (already written — do not re-propose these):');
    for (const step of projection) {
      const sid = step.step_id ?? step.id;
      const facts = Array.isArray(stepFindings[sid]) ? stepFindings[sid] : [];
      lines.push(`- [${step.status ?? 'unknown'}] ${step.name ?? step.step_id}`
        + (facts.length ? ` · ${facts.length} finding${facts.length === 1 ? '' : 's'} on file` : ''));
    }
    // WHAT THE CAMPAIGN HAS LEARNED (conditional — absent when nothing fed).
    // The glue John asked for: run findings inform the NEXT move, so the seat
    // sees them where it reasons, not stashed in a report nobody re-reads.
    const learned = [];
    for (const step of projection) {
      const sid = step.step_id ?? step.id;
      const facts = Array.isArray(stepFindings[sid]) ? stepFindings[sid] : [];
      for (const f of facts.slice(-4)) {
        learned.push(`- [${sid}] ${f.finding}${f.source ? ` (${f.source})` : ''}`);
      }
    }
    if (learned.length) {
      lines.push('', 'WHAT THE CAMPAIGN HAS LEARNED (from finished runs — use it to aim the next move):');
      lines.push(...learned.slice(0, 16));
    }
  } else {
    lines.push('', 'Confirmed roadmap steps: none yet.');
  }

  const confirmedKickoff = context.confirmed_kickoff;
  if (confirmedKickoff) {
    lines.push(
      '',
      `CONFIRMED KICKOFF v${confirmedKickoff.version} (authoritative intent):`,
      `Goal: ${confirmedKickoff.goal}`,
      `Work product: ${confirmedKickoff.work_product.name}`,
      `Components: ${confirmedKickoff.work_product.components.map((c) => `${c.id}=${c.name}`).join(' · ')}`,
      'Do not replace this confirmed version merely because a newer preview is open.',
    );
  }

  // LIVE RUNS ride the prompt so "is it running?" is answered from RECORDS,
  // never guessed. Deliberately CONDITIONAL: no runs → no block → prompts
  // without runs stay byte-identical (the recorded acceptance tape holds).
  const runs = Array.isArray(context.commission_runs) ? context.commission_runs : [];
  if (runs.length) {
    lines.push('', '--- COMMISSIONED RUNS (host records — the truth about what is running) ---');
    for (const r of runs.slice(0, 5)) {
      lines.push(
        `- ${r.skill ?? 'skill'} for step '${r.step_id ?? '?'}': ${r.outcome}`
        + (r.outcome === 'running' ? ` (launched ${r.at ?? '?'} — a live session is working now)` : '')
        + (r.needs ? ` — waiting on John: ${r.needs}` : ''),
      );
    }
    lines.push(
      'Answer any "is it running / what is happening" question FROM THIS LIST.',
      'A running entry means the machinery genuinely launched it — never deny or',
      're-propose a run this list already shows. John can watch a running session',
      'via its green Running strip in the chamber ("Open the session").',
    );
  }

  // ONCE THE CAMPAIGN IS RUNNING the conversation changes shape: it stops being about
  // the whole scaffolding and becomes about the step in hand. This is the difference
  // between a one-shot planner and a steward — John asked for detail to get filled in
  // by talking, step by step, rather than demanded up front.
  const active = context.active_step;
  if (active) {
    const gaps = Array.isArray(context.step_gaps) ? context.step_gaps : [];
    lines.push(
      '',
      `THE STEP IN HAND: "${active.name}" (${active.status}).`,
      active.done_when ? `Its done-when: ${active.done_when}` : '',
      active.oranges_annotations?.length
        ? `Foresight already recorded for it: ${active.oranges_annotations.join(' · ')}`
        : '',
      'Ask only for what THIS step needs to move — not for the whole campaign\'s detail.',
      'If it is finished, say what you think was learned and propose the next stage',
      '(set proposal.kind to "next_stage").',
    );
  }
  const done = projection.filter((s) => s.status === 'done').length;
  if (projection.length && done === projection.length) {
    lines.push('', 'Every confirmed step is done — the campaign needs its next stage.');
  }

  // The scaffolding-so-far. This is what makes turn N+1 a REFINEMENT rather than a
  // restart — without it he would have to re-describe the project every time.
  const open = context.open_proposal;
  if (open && open.kind === 'kickoff_proposal'
      && Array.isArray(open.plan_entries) && open.plan_entries.length) {
    lines.push(
      '',
      `KICKOFF SYNTHESIS v${open.version} (not confirmed — he is reacting to this):`,
      `Goal: ${open.goal}`,
      `Work product: ${open.work_product.name}`,
      `Components: ${open.work_product.components.map((c) => `${c.id}=${c.name}`).join(' · ')}`,
      `Plan entries: ${open.plan_entries.map((entry) => `${entry.id}=${entry.name}`).join(' · ')}`,
      open.integration
        ? `Integration: ${open.integration.summary} · proof: ${open.integration.proof.observable}`
        : 'Integration: not needed; this is a one-component effort.',
      'If he is refining it, return the WHOLE revised kickoff synthesis with the same stable IDs where meaning did not change.',
    );
  } else if (open && Array.isArray(open.steps) && open.steps.length) {
    lines.push('', 'SCAFFOLDING YOU ALREADY PROPOSED (not yet confirmed — he is reacting to this):');
    open.steps.forEach((s, i) => {
      lines.push(`${i + 1}. ${s.name}${s.done_when ? ` — done when: ${s.done_when}` : ''}`);
    });
    lines.push(
      'If he is refining it, return the WHOLE revised scaffolding, not just the changed part.',
    );
  }

  // THE DURABLE HISTORY — earlier sessions, so the steward can explain how the plan got
  // here rather than only what it currently is. Read for recall; never for state.
  const history = Array.isArray(context.history) ? context.history : [];
  if (history.length) {
    lines.push('', '--- EARLIER CONVERSATION ON THIS PROJECT (history, not state) ---');
    for (const t of history) {
      const who = t?.role === 'steward' ? SPELLING : 'John';
      const text = String(t?.text ?? '').trim();
      if (text) lines.push(`${who}${t.at ? ` [${String(t.at).slice(0, 10)}]` : ''}: ${text}`);
    }
    lines.push(
      'That history is a RECORD OF WHAT WAS SAID, not the current plan. Where it '
      + 'disagrees with the confirmed roadmap above, the roadmap is right.',
    );
  }
  if (context.history_unreadable) {
    lines.push('', 'NOTE: the earlier conversation history could not be read. Say so if it matters.');
  }

  // Turns from the live session the caller is holding — replayed for immediacy. They
  // land in the durable log once the turn succeeds.
  const turns = Array.isArray(opts.turns) ? opts.turns : [];
  if (turns.length) {
    lines.push('', '--- THIS SESSION SO FAR ---');
    for (const t of turns) {
      const who = t?.role === 'steward' ? SPELLING : 'John';
      const text = String(t?.text ?? '').trim();
      if (text) lines.push(`${who}: ${text}`);
    }
  }

  // THE ANSWER LAW (steward-e1 W2, E1). Deliberately CONDITIONAL — like the
  // COMMISSIONED RUNS block above: no enforceable bound (or no question this
  // turn) → no block → every existing prompt stays byte-identical and the
  // recorded acceptance tapes hold. The ids are DETERMINISTIC (computed by
  // the Anchor sibling's committed bound, never here) — the seat answers the
  // question; it never decides what counts as one.
  const e1 = opts.e1;
  const e1Questions = (e1 && e1.enforceable === true && Array.isArray(e1.questions))
    ? e1.questions.filter((q) => q && q.question_id) : [];
  if (e1Questions.length) {
    lines.push(
      '',
      '--- ANSWER LAW (E1 — the ratified bound) ---',
      `John's turn carries ${e1Questions.length} direct question(s), each with a machine id.`,
      '',
      'THIS SUPERSEDES THE REPLY FORMAT ABOVE FOR THIS TURN. The reply format',
      'enumerates its keys and says "reply with ONLY a JSON object", so a reply',
      'that honours it literally omits the key below and is then REFUSED — the',
      'answer you wrote is discarded and John sees a block instead of it. The',
      'object you return is the one described above WITH this key added:',
      '',
      '  "answer_references": [{"question_id": "<id, verbatim from the list below>",',
      '                         "answer_text": "<your explicit answer to that question>"}]',
      '',
      'One entry per id below, covering EVERY id. The engine structurally',
      'refuses to close a turn while any listed id lacks an answer-reference —',
      'never walk away from one. Answer the question in "say" as you normally',
      'would; answer_references is the machine-readable receipt, not a',
      'substitute for talking to him.',
    );
    for (const q of e1Questions) {
      lines.push(`- ${q.question_id}: "${String(q.text ?? '').trim()}"`);
    }
  }

  lines.push('', '--- JOHN JUST SAID ---', String(utterance ?? '').trim());
  return lines.join('\n');
}

export async function converse(projectPath, opts = {}) {
  // 0. MISSING and EMPTY are separate rows (Gate 5 / Wave 3): no utterance at all is not
  //    the same fact as an utterance with nothing in it, and neither is a seat failure.
  if (opts.utterance == null) {
    return kickoffTalkFailure(KICKOFF_TALK_CODE.MISSING, {
      error: 'utterance_missing',
      model_called: false,
    });
  }
  const utterance = String(opts.utterance);

  // 1. Control verbs never reach a model, and never spend.
  const routed = routeUtterance(utterance, { session: opts.session });
  if (routed.lane === 'refuse') {
    if (routed.reason === 'destructive_free_form') {
      return converseFailure(CONVERSE_CODE.DESTRUCTIVE, { error: routed.reason, routed: routed.lane });
    }
    return kickoffTalkFailure(KICKOFF_TALK_CODE.EMPTY, {
      error: routed.reason,
      routed: routed.lane,
      model_called: false,
    });
  }
  if (routed.lane === 'act') {
    return {
      ok: true,
      lane: 'act',
      compiled: routed.compiled,
      say: `Understood that as: ${routed.compiled.label ?? routed.compiled.act}.`,
      model_called: false,
      spent: false,
      ledger_write: false,
      dialogue_persisted: false,
    };
  }

  // 2. Rebuild durable context. A Face is a post-confirm projection, not a
  // brainstorming precondition; an empty project is valid kickoff context.
  const context = loadStewardContext(projectPath);
  if (!context.ok) {
    if (context.store_check) {
      // The store's own named row (unreadable / corrupt / bound) rides through unchanged.
      return {
        ...context.store_check,
        say: context.store_check.user_text,
        lane: 'converse',
        conversational: true,
        model_called: false,
        ledger_write: false,
        dialogue_persisted: false,
      };
    }
    return converseFailure(context.code ?? CONVERSE_CODE.KICKOFF_CORRUPT, {
      context_check: context,
    });
  }

  // 3. Seat must be safe BEFORE we send anything anywhere.
  const seats = opts.seats ?? resolveSeats({ prefs: opts.prefs, env: opts.env });
  if (!seats.ok || !isProductionSeatSafe(seats)) {
    return converseFailure(CONVERSE_CODE.SEAT_UNSAFE, {
      error: seats.error ?? 'seat_unsafe',
      seat_message: seats.message ?? null,
    });
  }

  // 4. BACKGROUND ALLOWANCE (John, 2026-08-05). Talking used to require confirming a
  //    budget before the steward would say anything: "I really don't want to do that.
  //    Might have like a background amount of effort and if it hits there then it can
  //    say hey we've hit this threshold do you want to carry on."
  //
  //    So an allowance opens ON ITS OWN the first time he talks. The law it replaces is
  //    "nothing spent without prior confirmation"; the law it keeps is the one that
  //    matters — the steward STOPS at the cap and asks, and cannot go past it without
  //    him saying so. Reaching the cap is a checkpoint (see BUDGET_REACHED below).
  let envState = readEnvelopeState(projectPath, {});
  if ((!envState.ok || !envState.live) && envState.code !== ENVELOPE_CODE.EXHAUSTED) {
    const opened = opts.openAllowance
      ? opts.openAllowance(projectPath)
      : { ok: false, skipped: 'no_opener_injected' };
    if (opened.ok) envState = readEnvelopeState(projectPath, {});
  }
  // THE SILENT BOOTSTRAP (Gate 5 / Wave 3). A new effort has no Face, no envelope, no
  // budget - and none of them is a precondition for brainstorming. Nothing is prompted
  // and nothing is written here: the Face is created ON confirmation and the envelope is
  // materialized INSIDE the confirmation receipt (Wave 2); until then the turn's spend
  // rides the result. An envelope that EXISTS keeps its own law below (debit; stop at
  // the cap and ask).
  const bootstrap = settleKickoffBootstrap({ face: context.narrative, envelope_state: envState });
  if ((!envState.ok || !envState.live) && !bootstrap.spend_deferred) {
    // A REACHED CAP IS A CHECKPOINT, NOT A WALL (John, 2026-08-04). Say what has
    // actually been spent and offer to carry on, rather than a bare refusal — the
    // decision to go past it is his, and it stays a human confirmation.
    if (envState.code === ENVELOPE_CODE.EXHAUSTED) {
      // readEnvelopeState nests the numbers under `balance` — reading them off the
      // top level silently yields undefined, and the checkpoint would have told John
      // "$0.00 of $0.00 spent", which is worse than no number at all.
      const bal = envState.balance ?? envState;
      const spent = Number(bal.spent_usd) || 0;
      const cap = bal.max_spend_usd;
      const onSpend = bal.bound !== 'compiles';
      return converseFailure(CONVERSE_CODE.BUDGET_REACHED, {
        code: CONVERSE_CODE.BUDGET_REACHED,
        status_code: CONVERSE_CODE.BUDGET_REACHED,
        bound: bal.bound ?? 'spend',
        spent_usd: spent,
        max_spend_usd: cap ?? null,
        envelope: envState,
        can_raise: onSpend,
        say: onSpend
          ? `We've reached the session budget — ${formatSpend(spent)} of `
            + `${formatSpend(cap ?? 0)} spent. I've stopped rather than keep `
            + 'spending. Tell me to carry on and I will, or raise the cap and we keep going.'
          : 'We\'ve reached this session\'s turn limit. Confirm a fresh budget and we carry on.',
      });
    }
    const code =
      envState.code === ENVELOPE_CODE.EXPIRED ? ENVELOPE_CODE.EXPIRED
      : CONVERSE_CODE.NO_ENVELOPE;
    return converseFailure(CONVERSE_CODE.NO_ENVELOPE, {
      code,
      status_code: code,
      envelope: envState,
    });
  }

  // 5. The seat call itself — injected, because engine/ may not spawn.
  //    The E1 bound payload (opts.e1, computed by the Anchor owner and
  //    injected at the bridge boundary) rides into the prompt's conditional
  //    ANSWER LAW block and into the turn-completion hook below.
  const prompt = buildStewardPrompt(context, utterance, { turns: opts.turns, e1: opts.e1 });
  if (typeof opts.seatCall !== 'function') {
    return converseFailure(CONVERSE_CODE.SEAT_UNREACHABLE, { error: 'no_seat_call_injected' });
  }

  // AFFORDABILITY, not just liveness. `live` only means "not yet over the cap" — an
  // envelope with a few cents left is live while the NEXT debit would be refused. Left
  // as-is the steward would spend a real model call and only then discover it could not
  // record the spend: money out, ledger silent. Stop at the checkpoint BEFORE the call.
  const balance = envState.balance ?? {};
  const remaining = balance.remaining_usd;
  if (remaining != null && Number.isFinite(Number(remaining))) {
    const estimate = Number(priceCompile(prompt, { seat: 'compile' }).cost_usd) || 0;
    if (estimate > Number(remaining)) {
      const spent = Number(balance.spent_usd) || 0;
      const cap = Number(balance.max_spend_usd) || 0;
      return converseFailure(CONVERSE_CODE.BUDGET_REACHED, {
        code: CONVERSE_CODE.BUDGET_REACHED,
        status_code: CONVERSE_CODE.BUDGET_REACHED,
        bound: 'spend',
        spent_usd: spent,
        max_spend_usd: cap,
        estimated_next_usd: estimate,
        can_raise: true,
        say:
          `This next turn would take us past the session budget — ${formatSpend(spent)} of `
          + `${formatSpend(cap)} spent already. I've stopped rather than run it. `
          + 'Raise the cap and I will carry straight on.',
      });
    }
  }

  const callSeat = async (text, role) => {
    try {
      return await opts.seatCall(text, {
        seat_family: seats.coding_family,
        driver: seats.coding_driver,
        role,
        // Only the planning turn is granted read-only project access.
        project_path: context.project_path,
      });
    } catch (e) {
      return { ok: false, reason: 'seat_call_threw', detail: String(e?.message ?? e) };
    }
  };

  // TALK FIRST, ALWAYS. The conversational tier holds the exchange and cannot write a
  // scaffolding — so the steward can never open by dumping a finished plan on him.
  let seatResult = await callSeat(prompt, SEAT_ROLE.CONVERSATIONAL);
  if (!seatResult || seatResult.ok !== true || !String(seatResult.text ?? '').trim()) {
    return converseFailure(CONVERSE_CODE.SEAT_UNREACHABLE, {
      error: 'seat_call_failed',
      reason: seatResult?.reason ?? 'no_reply',
      detail: seatResult?.detail,
    });
  }

  // 6. Parse strictly. An unreadable reply is reported, never salvaged.
  let parsed = parseStewardReply(seatResult.text);
  if (!parsed.ok) return { ...parsed, seat_reached: true };

  // PLAN SECOND, RARELY. Only when the conversation earned it does the FRONTIER tier
  // run — the slow, deep, expensive turn — and only that turn may frame a scaffolding.
  // A compact provisional proposal can be explicitly requested. The number of
  // exchanges never overrides adaptive discovery or the retained answers.
  const turnNumber = kickoffTurnNumber(opts.turns);
  const thinTurn = kickoffNeedsThinProposal({
    explicit_thin_proposal: opts.thin_proposal === true,
    turn_number: turnNumber,
    open_proposal: context.open_proposal,
    confirmed_kickoff: context.confirmed_kickoff,
    step_count: context.projection.length,
  });
  const planForced = thinTurn && parsed.reply.wants_plan !== true && !parsed.reply.proposal;
  let planUsage = null;
  if (parsed.reply.wants_plan === true || planForced) {
    const planPrompt = buildStewardPrompt(context, utterance, {
      turns: opts.turns,
      planning: true,
      plan_brief: parsed.reply.plan_brief,
      e1: opts.e1,
      thin_turn: thinTurn ? turnNumber : null,
    });
    const planResult = await callSeat(planPrompt, SEAT_ROLE.FRONTIER);
    if (planResult?.ok === true && String(planResult.text ?? '').trim()) {
      const planParsed = parseStewardReply(planResult.text);
      if (planParsed.ok && planParsed.reply.proposal) {
        // Keep the talking turn's voice; take the frontier turn's plan.
        // E1: the talking turn's answer-references survive the merge — a
        // question the first turn answered must not become unanswered
        // because the frontier turn framed a plan.
        const talkRefs = Array.isArray(parsed.reply.answer_references)
          ? parsed.reply.answer_references : [];
        const planRefs = Array.isArray(planParsed.reply.answer_references)
          ? planParsed.reply.answer_references : [];
        parsed = {
          ok: true,
          reply: {
            ...planParsed.reply,
            asks: parsed.reply.asks,
            gathering: false,
            answer_references: planRefs.length ? planRefs : talkRefs,
          },
        };
        planUsage = planResult.meta ?? null;
      }
    }
    // A failed planning turn is NOT a failed turn: he still gets the conversation, and
    // the steward says plainly that the framing did not come back rather than inventing
    // one. Falling through leaves `parsed` as the talking reply.
  }

  const meta = sanitizeSeatMeta({
    ...(seatResult.meta ?? {}),
    // A planning turn's tokens are the bulk of the spend — count both, or the debit
    // under-reports what was actually used.
    tokens: (Number(seatResult.meta?.tokens) || 0) + (Number(planUsage?.tokens) || 0),
    // Real dollars, both turns. The planning turn is the expensive one.
    cost_usd: (Number(seatResult.meta?.cost_usd) || 0) + (Number(planUsage?.cost_usd) || 0),
    seat_family: seats.coding_family,
    driver: seats.coding_driver,
  });
  // ACT on the check rather than merely computing it. An unread `ok` is a guard that
  // looks like protection and provides none — the exact shape this project has shipped
  // three times. If a vendor product model id reached the whitelist anyway, drop the
  // identity fields so nothing durable can carry one, and say so out loud.
  if (!meta.ok) {
    meta.usage.seat_family = null;
    meta.usage.driver = null;
    meta.usage.scrubbed_product_model_ids = meta.product_model_ids.length;
  }
  const reply = parsed.reply;

  // THE QUESTION CAP (Gate 5 / Wave 3): at most one natural question per turn, the North
  // Star's letter. The seat may write more; one is delivered and the rest are reported held.
  const capped = capKickoffQuestions(reply.asks);
  reply.asks = capped.asks;
  const questionsHeld = capped.held.length;

  // ONE debit seam for the closes below. With no envelope at all (a new effort) the spend
  // is DEFERRED - it rides the result and is materialized inside the confirmation receipt
  // - never silently dropped and never prompted for.
  const debitTurn = (suffix) => {
    if (bootstrap.spend_deferred) {
      return {
        ok: true,
        debited: false,
        deferred: true,
        deferred_to: bootstrap.envelope_materialized_in,
        tokens: meta.usage.tokens,
        cost_usd: meta.usage.cost_usd,
      };
    }
    return debitSessionEnvelope(projectPath, {
      kind: 'compile',
      text: prompt,
      tokens: meta.usage.tokens || undefined,
      cost_usd: meta.usage.cost_usd,
      auth: opts.auth,
      client_event_id: opts.client_event_id ? `${opts.client_event_id}-${suffix}` : undefined,
    });
  };
  const debitView = (debit) => (debit.deferred
    ? debit
    : debit.ok ? { debited: true, shown: debit.shown } : { debited: false, ...debit });

  // ── THE E1 TURN-COMPLETION HOOK (steward-e1 W2 — the W8 row) ─────────────
  // The turn attempts to close HERE. Under a RATIFIED bound, an open
  // question id with no typed answer-reference structurally blocks the
  // close with a named finding; an unratified/absent bound fails CLOSED by
  // name on the verdict (never a silent clean pass) without blocking. The
  // seat call already happened, so the spend is debited honestly either way
  // — a blocked turn never hides money that left.
  const turnClose = enforceTurnCompletion(reply, opts.e1 ?? null);
  if (turnClose.decision === E1_DECISION.BLOCK) {
    const debit = debitTurn('blocked');
    return {
      ok: true,
      lane: 'converse',
      turn_blocked: true,
      blocked: {
        finding: turnClose.finding,
        unanswered: turnClose.unanswered,
        // Nothing is lost: the reply is HELD, not delivered as a closed
        // turn — the drawn refusal state (V5 AG-BLOCKED-TURN) is what John
        // sees, so the cure never looks like "are you working".
        held_say: reply.say,
        message: 'The engine refused to close this turn: a direct question '
          + 'from John still lacks a typed answer-reference.',
      },
      turn_close: turnClose,
      say: 'The engine refused to close this turn: a direct question from '
        + 'John still lacks a typed answer-reference.',
      model_called: true,
      seat: { family: seats.coding_family, driver: seats.coding_driver },
      usage: meta.usage,
      debit: debitView(debit),
      steps_written: false,
      ledger_write: false,
      dialogue_persisted: false,
    };
  }

  // THE AMBIGUOUS ROW (Gate 5 / Wave 3): the thin turn came and went and the seat still
  // has no bundle. Named, with NO question attached (never a third question); the spend
  // is accounted honestly; nothing is written and the exchange is not recorded as a close.
  if (thinTurn && !reply.proposal) {
    const debit = debitTurn('ambiguous');
    return kickoffTalkFailure(KICKOFF_TALK_CODE.AMBIGUOUS, {
      error: 'no_bundle_by_thin_turn',
      turn: turnNumber,
      turn_number: turnNumber,
      plan_forced: planForced,
      held_say: reply.say,
      questions_held: questionsHeld + reply.asks.length,
      gathering: true,
      model_called: true,
      seat: { family: seats.coding_family, driver: seats.coding_driver },
      usage: meta.usage,
      debit: debitView(debit),
      turn_close: turnClose,
      steps_written: false,
      bootstrap,
    });
  }

  // Record the exchange. Durable, append-only, and NEVER authoritative: this is how
  // John reads back why the plan changed, not where the plan currently stands.
  const recordTurns = (proposalHash, itemCount = 0, proposalKind = 'scaffold') => {
    const appended = appendConversationTurns(
      projectPath,
      [{ role: 'john', text: utterance }, { role: 'steward', text: reply.say }],
      {
        proposal_hash: proposalHash ?? null,
        kind: proposalHash ? `${proposalKind}_proposed` : 'conversation',
        at: opts.at,
      },
    );
    // Portfolio memory: WHAT THE STEWARD DID, never what the project is. Best-effort —
    // the steward's own bookkeeping must not break a turn John cares about.
    noteStewardEffort({
      kind: proposalHash ? `${proposalKind}_proposed` : 'conversation',
      project_path: projectPath,
      project_id: opts.project_id ?? context.strip?.project_id ?? null,
      at: opts.at,
      summary: proposalHash
        ? proposalKind === 'kickoff'
          ? `Proposed kickoff synthesis v${reply.proposal?.version ?? 'next'} with ${itemCount} plan entries`
          : `Proposed a ${itemCount}-stage scaffolding`
        : 'Talked through the project; no proposal yet',
    });
    if (reply.asks?.length) {
      noteStewardEffort({
        kind: 'question_raised',
        project_path: projectPath,
        project_id: opts.project_id ?? context.strip?.project_id ?? null,
        at: opts.at,
        summary: reply.asks[0],
      });
    }
    return appended;
  };

  // STEWARD FEEDBACK LANDS FOR REAL. The seat used to SAY "journaled" with no
  // hands (fabricated act, caught live 2026-08-06); now the reply's typed
  // journal entries are written durably here, and only this makes it true.
  let journaled = null;
  if (Array.isArray(reply.journal) && reply.journal.length) {
    const fed = appendStewardFeedback(projectPath, reply.journal, { at: opts.at });
    journaled = fed.ok
      ? { entries: fed.appended }
      : { entries: 0, error: fed.error };
  }

  // DETAIL ACCRUES BY TALKING. When he answered something the step in hand was missing,
  // it lands as a typed elaboration_answer on the spine — so the plan fills in as the
  // conversation goes, and he never has to sit down and scaffold it all up front.
  let elaborated = null;
  if (reply.answers && context.active_step && Object.keys(reply.answers).length) {
    const rec = recordElaborationAnswers(projectPath, {
      step_id: context.active_step.step_id ?? context.active_step.id,
      answers: reply.answers,
      who: opts.who ?? 'john',
      at: opts.at,
    });
    elaborated = rec.ok
      ? { recorded: Object.keys(reply.answers), step_id: rec.step_id ?? null }
      : { recorded: [], error: rec.error ?? rec.code };
  }

  // 7. No proposal yet — still gathering. Debit the call that was actually made.
  if (!reply.proposal) {
    const logged = recordTurns(null);
    const debit = debitTurn('turn');
    return {
      ok: true,
      lane: 'converse',
      say: reply.say,
      asks: reply.asks,
      gathering: true,
      proposal: null,
      turn_number: turnNumber,
      questions_held: questionsHeld,
      plan_forced: planForced,
      bootstrap,
      // E1 (steward-e1 W2): every converse close carries its turn-close
      // verdict — an unenforceable bound rides BY NAME, never silently open.
      turn_close: turnClose,
      model_called: true,
      seat: { family: seats.coding_family, driver: seats.coding_driver },
      usage: meta.usage,
      debit: debitView(debit),
      // Said explicitly rather than left undefined: a talking turn writes no steps, and
      // a caller checking `steps_written === false` deserves a true answer, not absence.
      steps_written: false,
      elaborated,
      journaled,
      // The chamber shows the commission card on this signal — the model
      // routes "start Gandalf" here instead of pretending work began.
      wants_commission: reply.wants_commission === true,
      commission_skill: reply.commission_skill ?? null,
      commission_directive: reply.commission_directive ?? null,
      // Spoken project management from the High Seat: the host renders the
      // confirm card; nothing is created until John clicks it.
      project_create: reply.project_create ?? null,
      ledger_write: false,
      // The transcript IS now kept (durable, non-authoritative). Say so honestly
      // rather than leaving a stale `false` that misdescribes what happened.
      dialogue_persisted: logged.ok === true,
      conversation_log: logged.ok
        ? { appended: logged.appended, total: logged.total }
        : { appended: 0, error: logged.error ?? logged.code },
    };
  }

  // 8. A proposal. New kickoff synthesis uses its own strict lineage; legacy
  // scaffolding remains available for recorded replies and established callers.
  const kickoffProposal = reply.proposal.kind === 'kickoff';
  let proposed;
  let legacyRoadmap = null;
  if (kickoffProposal) {
    const debit = debitTurn('kickoff-debit');
    if (!debit.ok) {
      return {
        ...debit,
        lane: 'converse',
        say: reply.say,
        asks: reply.asks,
        model_called: true,
        conversational: true,
      };
    }
    // THE STORE is the lineage of record (Gate 5 / Wave 2's one store): the WHOLE bundle,
    // v1 on an empty lineage, superseding at the same version before a confirmation,
    // v(n+1) after one. The host asserts which seat authored it; nothing else is written.
    const host = {
      seat_family: meta.usage.seat_family,
      driver: meta.usage.driver,
      source_turn_id: opts.client_event_id ?? null,
      client_event_id: opts.client_event_id
        ? `${opts.client_event_id}-kickoff-propose` : undefined,
      at: opts.at,
    };
    proposed = openKickoffBundle(projectPath, {
      bundle: reply.proposal,
      ...host,
      timeoutMs: opts.timeoutMs,
    });
    if (proposed.ok && usesLegacyRoadmapLane(context)) {
      // THE LEGACY LANE: a stood-up campaign (a Face on disk) keeps the pre-Gate-5
      // roadmap-ledger kickoff path beside the store - the WH4 lane's interaction,
      // unchanged. Same bundle, same seat lineage, same source turn: the same hash on an
      // agreeing lineage. A NEW effort never reaches this branch and writes only the store.
      const mirrored = proposeKickoff(projectPath, {
        proposal: reply.proposal,
        project_id: opts.project_id ?? context.strip?.project_id ?? null,
        ...host,
      });
      legacyRoadmap = mirrored.ok
        ? {
          written: mirrored.event != null,
          proposal_hash: mirrored.proposal_hash,
          diverged: mirrored.proposal_hash !== proposed.proposal_hash,
        }
        : { written: false, code: mirrored.code, error: mirrored.error };
    }
    if (proposed.ok) {
      proposed.debit = debit.deferred
        ? debit
        : {
          ok: true,
          debited: true,
          shown: debit.shown,
          cost_usd: debit.shown?.cost_usd ?? debit.pricing?.cost_usd,
          envelope_id: debit.envelope_id ?? debit.envelope?.envelope_id,
          pricing: debit.pricing,
        };
    }
  } else {
    proposed = proposeScaffolding(projectPath, {
      goal: reply.proposal.goal,
      stages: reply.proposal.stages.map((s) => ({
        name: s.name,
        done_when: s.done_when,
        oranges: s.oranges,
        ...(s.step_type ? { step_type: s.step_type } : {}),
      })),
      tokens: meta.usage.tokens || undefined,
      cost_usd: meta.usage.cost_usd,
      auth: opts.auth,
      client_event_id: opts.client_event_id ? `${opts.client_event_id}-propose` : undefined,
      at: opts.at,
    });
  }

  if (!proposed.ok) {
    return {
      ...proposed,
      lane: 'converse',
      say: reply.say,
      asks: reply.asks,
      model_called: true,
      conversational: true,
    };
  }

  // Tagged with the proposal hash, so the reasoning can be read alongside the exact
  // proposal version it produced — the "how did we get here" John asked for.
  const itemCount = kickoffProposal
    ? proposed.proposal.plan_entries.length
    : proposed.proposal.steps.length;
  const logged = recordTurns(
    proposed.proposal_hash,
    itemCount,
    kickoffProposal ? 'kickoff' : 'scaffold',
  );

  return {
    ok: true,
    lane: 'converse',
    say: reply.say,
    asks: reply.asks,
    gathering: false,
    // E1 (steward-e1 W2): the proposal close carries its verdict too.
    turn_close: turnClose,
    conversation_log: logged.ok
      ? { appended: logged.appended, total: logged.total }
      : { appended: 0, error: logged.error ?? logged.code },
    proposal: proposed.proposal,
    proposal_hash: proposed.proposal_hash,
    proposal_id: proposed.proposal_id,
    proposal_kind: reply.proposal.kind,
    ...(kickoffProposal
      ? {
        plan_entry_count: proposed.proposal.plan_entries.length,
        // What the chamber shows and sends back: the prose John reads and BOTH hashes the
        // confirmation binds. State is the store's; the roadmap mirror is named beside it.
        rendered_prose: proposed.rendered_prose,
        rendered_prose_hash: proposed.rendered_prose_hash,
        version: proposed.version,
        prior_confirmed_hash: proposed.prior_confirmed_hash ?? null,
        supersedes: proposed.supersedes ?? null,
        kickoff_state: proposed.state,
        kickoff_phase: proposed.phase,
        legacy_roadmap: legacyRoadmap,
        turn_number: turnNumber,
        questions_held: questionsHeld,
        plan_forced: planForced,
        bootstrap,
      }
      : {
        foresight: reply.proposal.foresight,
        step_count: proposed.proposal.steps.length,
      }),
    model_called: true,
    seat: { family: seats.coding_family, driver: seats.coding_driver },
    usage: meta.usage,
    debit: proposed.debit,
    steps_written: false,
    elaborated,
    journaled,
    ledger_write: proposed.event != null,
    authoritative: false,
    applied: false,
    dialogue_persisted: logged.ok === true,
    confirm_hint: kickoffProposal
      ? 'This is a preview, not project truth — confirm this exact version to apply it.'
      : 'Nothing is written yet — confirm and these become the campaign roadmap.',
  };
}

export function proposeBoundCommission(opts = {}) {
  if (opts.skip_precondition !== true) {
    const pre = assertCommissionPreconditions({
      root: opts.root ?? DEFAULT_ROOT,
      fallback: opts.precondition_fallback ?? null,
    });
    if (!pre.ok) {
      return commissionFailure(COMMISSION_CODE.PRECONDITION_HALT, {
        error: 'precondition-halt',
        halt: pre.halt,
        g4: pre.g4,
        sc6: pre.sc6,
        message: pre.message,
      });
    }
  }

  const step_id = opts.step_id ?? opts.step ?? null;
  if (!nonEmpty(step_id)) {
    return commissionFailure(COMMISSION_CODE.STEP_UNBOUND, {
      error: 'step-not-found',
      state: 'free-floating',
    });
  }

  const validated = validateRoadmap(opts.roadmap ?? null);
  if (!validated.ok) {
    return commissionFailure(COMMISSION_CODE.STORE_UNREADABLE, {
      error: validated.error ?? 'roadmap-unreadable',
      message: validated.message ?? COMMISSION_TEXT[COMMISSION_CODE.STORE_UNREADABLE],
      detail: validated,
    });
  }
  const step = validated.projection.find((s) => s.id === step_id) ?? null;
  if (!step) {
    return commissionFailure(COMMISSION_CODE.STEP_UNBOUND, {
      error: 'step-not-found',
      step_id,
    });
  }

  // Dispatch by locked step-type map when skill omitted or step_type given.
  let skillInput = opts.skill ?? null;
  let step_type = opts.step_type ?? step.step_type ?? step.type ?? null;
  if (!skillInput && step_type) {
    const mapped = skillForStepType(step_type);
    if (mapped.ok) skillInput = mapped.skill;
  }
  // BUILD default when name/status hints (GWT: BUILD step → Foreman)
  if (!skillInput && step_type) {
    const upper = String(step_type).toUpperCase();
    if (STEP_TYPE_SKILL_MAP[upper]) {
      skillInput = STEP_TYPE_SKILL_MAP[upper].skill;
    }
  }

  const tableLoad = loadSkillsTable({
    root: opts.root,
    skills_table: opts.skills_table,
  });
  if (!tableLoad.ok) {
    return commissionFailure(COMMISSION_CODE.STORE_UNREADABLE, {
      error: 'skills-table-unreadable',
      message: tableLoad.message,
    });
  }

  const selected = selectCommissionableSkill(skillInput, tableLoad.table);
  if (!selected.ok) {
    return commissionFailure(COMMISSION_CODE.SKILL_REFUSED, {
      error: 'skill-not-commissionable',
      skill: selected.skill,
      excluded_reason: selected.excluded_reason,
      message: selected.message,
    });
  }
  const skill = selected.skill;

  // Seats law: resolveSeats → subscription CLIs only
  // Forward exists/readFile so host-less callers (T-HOST-0) can force defaults
  // without silently reading the machine ~/.anchor store.
  const seats =
    opts.seats && typeof opts.seats === 'object'
      ? opts.seats
      : resolveSeats({
          prefs: opts.prefs ?? null,
          env: opts.env,
          prefsPath: opts.prefsPath,
          exists: opts.exists,
          readFile: opts.readFile,
        });

  if (!seats || seats.ok === false || !isProductionSeatSafe(seats)) {
    return commissionFailure(COMMISSION_CODE.SEAT_REFUSED, {
      error: 'seat-not-subscription',
      seats,
    });
  }

  // Seat-collision pure predicate
  const collision = hasSeatCollision(
    {
      coding_family: seats.coding_family,
      coding_driver: seats.coding_driver,
      review_family: seats.review_family,
      review_driver: seats.review_driver,
    },
    opts.live_runs,
  );
  if (collision.collision) {
    return commissionFailure(COMMISSION_CODE.SEAT_COLLISION, {
      error: 'seat-collision',
      family: collision.family,
      driver: collision.driver,
      live_run: collision.run,
    });
  }

  const depth_cell = opts.depth_cell ?? opts.depth ?? 'LITE';
  const estimate = estimateCommissionSpend({
    skill,
    depth_cell,
    step_name: step.name,
  });

  const seatStamp = {
    coding_family: seats.coding_family,
    review_family: seats.review_family,
    default_cli: seats.default_cli ?? null,
    coding_driver: seats.coding_driver,
    review_driver: seats.review_driver,
    cross_model: seats.cross_model,
    source: seats.prefs_source ?? seats.source ?? 'prefs_or_defaults',
    subscription_only: true,
  };

  const commission = buildCommission({
    skill,
    depth_cell,
    active_effort: step.name,
    project_cwd: opts.project_cwd ?? null,
    seats,
    prefs: opts.prefs ?? null,
    env: opts.env,
    prefsPath: opts.prefsPath,
    commission_id: opts.commission_id ?? null,
  });
  if (!commission.ok) {
    return commissionFailure(COMMISSION_CODE.SEAT_REFUSED, {
      error: commission.error ?? 'commission-build-failed',
      message: commission.message,
      commission,
    });
  }

  const hashBody = proposalHashBody({
    skill,
    seat: seatStamp,
    depth_cell,
    estimate,
  });
  const proposal_hash = hashCommissionProposal(hashBody);
  const at = opts.at ?? todayIso();

  const proposal = {
    ok: true,
    spelling: SPELLING,
    schema: COMMISSION_PROPOSAL_SCHEMA,
    kind: 'commission_proposal',
    proposal_id: `ecgberht-proposal-${step_id}-${proposal_hash.slice(0, 12)}`,
    proposal_hash,
    step_id,
    step,
    step_type: step_type ?? null,
    skill,
    depth_cell,
    seat: seatStamp,
    seats: seatStamp,
    estimate,
    rendering: {
      skill,
      seat: seatStamp.coding_driver ?? seatStamp.coding_family,
      depth: depth_cell,
      estimate_usd: estimate.cost_usd,
      estimate_tokens: estimate.tokens,
      summary: `Commission ${skill} at depth ${depth_cell} on seat ${seatStamp.coding_driver} (~$${estimate.cost_usd} synthetic) for step ${step_id}.`,
      disclaimer: COST_MODEL_DISCLAIMER,
    },
    proposed_by: opts.who ?? 'ecgberht-steward',
    at,
    commission,
    job_runner: ANCHOR_JOB_COMPOSE,
    requires_confirm: true,
    confirmed: false,
    run_started: false,
    primary_ux: COMMISSION_PRIMARY_UX,
    mode_picker_primary: false,
    single_writer: ROADMAP_SINGLE_WRITER,
    table_bound: true,
    seats_law: true,
    message: `Steward proposes commissioning ${skill} for step '${step_id}' (seat ${seatStamp.coding_driver}, depth ${depth_cell}, estimate $${estimate.cost_usd} synthetic). Confirm or refuse — nothing runs until confirm.`,
  };

  // T-ATT-CS1: commission proposed / awaiting confirm → publish at the propose verb.
  let attention_publish = null;
  const projectPath = opts.project_cwd ?? opts.project_path ?? opts.projectPath ?? null;
  if (projectPath && opts.skip_attention_publish !== true) {
    attention_publish = publishAttention(projectPath, {
      // T-ATT-CS1
      call_site: ATTENTION_CALL_SITES.PROPOSE,
      who: opts.who ?? 'ecgberht-steward',
      at,
      seed: opts.roadmap ?? opts.seed,
      skip_index: true,
      ledgerView: {
        events: opts.roadmap?.roadmap_events ?? [],
        projection: validated.projection ?? [],
        awaiting_confirm: true,
        commission_proposal: proposal,
        at,
      },
      home: opts.home,
      env: opts.env,
      project_id: opts.project_id,
      skip_brief_cache: opts.skip_brief_cache === true,
    });
  }

  return {
    ...proposal,
    attention_publish,
  };
}

export function confirmBoundCommission(opts = {}) {
  const proposal = opts.proposal;
  if (
    !proposal ||
    typeof proposal !== 'object' ||
    proposal.kind !== 'commission_proposal' ||
    proposal.requires_confirm !== true
  ) {
    return commissionFailure(COMMISSION_CODE.STATE_UNKNOWN, {
      error: 'commission_confirm_requires_proposal',
      message:
        'Confirm needs a steward commission_proposal (propose/confirm path — not a mode picker).',
    });
  }

  const who = normalizeWho(opts.who);
  if (!who) {
    return commissionFailure(COMMISSION_CODE.STATE_UNKNOWN, {
      error: 'commission_confirm_requires_who',
      message: 'Commission confirm is a human decision — pass who confirmed.',
      required: ['who'],
    });
  }

  // Auth via injected authorizer — never a token check inside the engine
  const authCtx = opts.authCtx ?? { principal: who.claimed };
  const decision = authorize('confirm', authCtx);
  if (!decision.ok) {
    return commissionFailure(COMMISSION_CODE.AUTH_REFUSED, {
      error: decision.code ?? 'auth-refused',
      message: decision.message ?? COMMISSION_TEXT[COMMISSION_CODE.AUTH_REFUSED],
      auth: decision,
      bind_appended: false,
      processes_launched: 0,
    });
  }

  // Hash-bound TOCTOU
  const expectedHash = recomputeProposalHash(proposal);
  const providedHash =
    opts.proposal_hash ?? proposal.proposal_hash ?? '';
  if (!providedHash || providedHash !== expectedHash) {
    return commissionFailure(COMMISSION_CODE.CONFIRM_HASH_MISMATCH, {
      error: 'confirm-hash-mismatch',
      presented_hash: providedHash || null,
      expected_hash: expectedHash,
      processes_launched: 0,
      bind_appended: false,
    });
  }

  const client_event_id =
    opts.client_event_id ??
    `confirm-${proposal.proposal_id ?? proposal.proposal_hash ?? 'anon'}`;

  // T-IDEM-11: double submit → original job_id, no second bind/launch
  const idemKey = opts.project_path
    ? `${path.resolve(opts.project_path)}::${client_event_id}`
    : `mem::${client_event_id}`;
  if (_idempotenceCache.has(idemKey)) {
    const prior = _idempotenceCache.get(idemKey);
    return {
      ...prior,
      ok: true,
      idempotent: true,
      already_confirmed: true,
      skip_write: true,
      second_bind: false,
      second_launch: false,
      processes_launched: 0,
      message: `Commission already confirmed (client_event_id=${client_event_id}); original job_id returned, no second bind or launch.`,
    };
  }

  const at = opts.at ?? todayIso();
  const job_id =
    opts.job_id ??
    `ecgberht-job-${String(proposal.skill).toLowerCase()}-${proposal.proposal_hash.slice(0, 10)}`;
  const commissioned_as = `${proposal.skill}:${job_id}`;

  let roadmap = opts.roadmap ?? null;
  let roadmap_event = null;
  let projection = null;
  let strip = opts.strip ?? null;
  let strip_appended = false;
  let strip_instrument = null;
  let durable = false;
  let confirm_journal = false;
  let sot_written = false;

  if (opts.project_path) {
    // Wave 7 confirm journal (spine path)
    const journaled = confirmCommissionJournaled({
      project_path: opts.project_path,
      proposal: { ...proposal, requires_confirm: true },
      roadmap,
      strip,
      who: who.claimed,
      at,
      job_id,
      client_event_id,
      project_id: opts.project_id ?? null,
      home: opts.home,
    });
    if (!journaled.ok && !journaled.killed) {
      return commissionFailure(COMMISSION_CODE.STATE_UNKNOWN, {
        error: journaled.error ?? 'confirm-journal-failed',
        message: journaled.message,
        detail: journaled,
      });
    }
    roadmap = journaled.roadmap ?? roadmap;
    roadmap_event = journaled.roadmap_event ?? null;
    projection = journaled.projection ?? null;
    strip = journaled.strip ?? strip;
    strip_appended = journaled.strip_appended === true;
    strip_instrument = journaled.strip_instrument ?? null;
    durable = true;
    confirm_journal = true;
    sot_written = journaled.ok === true && journaled.killed !== true;
  } else {
    // In-memory bind for dry-run / fixtures
    const bindEvent = {
      kind: 'commission_bind',
      step_id: proposal.step_id,
      commissioned_as,
      at,
      client_event_id,
      proposal_hash: expectedHash,
    };
    if (roadmap) {
      const bound = appendRoadmapEvent(roadmap, bindEvent, { at });
      if (!bound.ok) {
        return commissionFailure(COMMISSION_CODE.STATE_UNKNOWN, {
          error: bound.error ?? 'bind-failed',
          message: bound.message,
          detail: bound,
        });
      }
      roadmap = bound.roadmap;
      roadmap_event = bound.event;
      projection = bound.projection;
    }
    if (strip) {
      strip_instrument = {
        _kind: 'instrument',
        kind: 'commission_confirm',
        as_of: at,
        job_id,
        commission_id: proposal.commission?.commission_id ?? null,
        step_id: proposal.step_id,
        skill: proposal.skill,
        depth_cell: proposal.depth_cell ?? null,
        state: 'queued',
        who: who.claimed,
        client_event_id,
        proposal_hash: expectedHash,
      };
      const appended = appendStripInstrument(strip, strip_instrument, {
        apply_to_projection: false,
      });
      if (!appended.ok) {
        return commissionFailure(COMMISSION_CODE.STATE_UNKNOWN, {
          error: 'strip-append-failed',
          message: appended.message,
        });
      }
      strip = appended.strip;
      strip_appended = true;
    }
  }

  const job = {
    schema: JOB_SCHEMA_ID,
    job_id,
    commission_id: proposal.commission?.commission_id ?? null,
    proposal_id: proposal.proposal_id ?? null,
    proposal_hash: expectedHash,
    step_id: proposal.step_id,
    skill: proposal.skill,
    depth_cell: proposal.depth_cell ?? null,
    seat: proposal.seat ?? proposal.seats ?? null,
    estimate: proposal.estimate ?? null,
    confirmed_by: who,
    confirmed: true,
    runner: ANCHOR_JOB_COMPOSE.runner,
    compose: ANCHOR_JOB_COMPOSE,
    spawn: proposal.commission ?? null,
    state: 'queued',
    commissioned_as,
    lifecycle_events: [
      {
        seq: 1,
        from: null,
        to: 'queued',
        at,
        observed: 'commission_confirm',
        who: who.claimed,
      },
    ],
  };

  // Dossier: confirmation recorded; launch identity filled by executor
  let dossier = null;
  if (opts.project_path) {
    const up = upsertDossier(opts.project_path, {
      job_id,
      commissioned_as,
      proposal: {
        proposal_id: proposal.proposal_id,
        proposal_hash: expectedHash,
        skill: proposal.skill,
        step_id: proposal.step_id,
        depth_cell: proposal.depth_cell,
        seat: proposal.seat,
        estimate: proposal.estimate,
      },
      confirmation: {
        who,
        at,
        client_event_id,
        proposal_hash: expectedHash,
        confirmed: true,
      },
    });
    if (up.ok) dossier = up.dossier;
  } else {
    dossier = {
      ...emptyDossier(job_id, commissioned_as),
      proposal: {
        proposal_id: proposal.proposal_id,
        proposal_hash: expectedHash,
        skill: proposal.skill,
        step_id: proposal.step_id,
      },
      confirmation: {
        who,
        at,
        client_event_id,
        proposal_hash: expectedHash,
        confirmed: true,
      },
    };
  }

  // Executor seam — ONLY path to launch
  let executor_result = null;
  let launched = false;
  let confirmed_and_unlaunched = false;
  let no_executor_host = false;
  let processes_launched = 0;
  let pid = null;
  let proc_create_time = null;

  if (opts.skip_executor !== true) {
    executor_result = executeCommission(
      {
        ...job,
        confirmed: true,
        confirmation: dossier?.confirmation ?? { confirmed: true, who },
        dossier,
      },
      {
        confirmed: true,
        who,
        project_path: opts.project_path ?? null,
        // Launch-seam revalidation is opt-in via executor_ctx.authCtx (or a
        // direct executeCommission call). Do NOT auto-forward confirm authCtx:
        // confirm already authorized; Wave 19 launch refusals are proven on
        // the executeCommission path (auth outcome sweep), and auto-forward
        // would re-hit authorize('launch') on every confirm+launch.
        ...(opts.executor_ctx ?? {}),
      },
    );

    if (
      executor_result &&
      executor_result.code === COMMISSION_CODE.NO_EXECUTOR_HOST
    ) {
      no_executor_host = true;
      confirmed_and_unlaunched = true;
      launched = false;
      processes_launched = 0;
      // Preserve confirmed state by name on dossier
      if (opts.project_path && dossier) {
        upsertDossier(opts.project_path, {
          job_id,
          commissioned_as,
          confirmation: {
            ...(dossier.confirmation ?? {}),
            confirmed: true,
            launch_state: 'confirmed-and-unlaunched',
            no_executor_host: true,
          },
          launch: {
            state: 'confirmed-and-unlaunched',
            no_executor_host: true,
            pid: null,
            proc_create_time: null,
            at,
          },
        });
      } else if (dossier) {
        dossier.launch = {
          state: 'confirmed-and-unlaunched',
          no_executor_host: true,
          pid: null,
          proc_create_time: null,
          at,
        };
        dossier.confirmation = {
          ...(dossier.confirmation ?? {}),
          launch_state: 'confirmed-and-unlaunched',
          no_executor_host: true,
        };
      }
    } else if (executor_result && executor_result.ok !== false) {
      launched = executor_result.launched !== false;
      processes_launched = launched ? 1 : 0;
      pid = executor_result.pid ?? null;
      proc_create_time = executor_result.proc_create_time ?? null;
      if (launched && (pid != null || proc_create_time != null)) {
        if (opts.project_path) {
          recordLaunchOnDossier(opts.project_path, {
            job_id,
            commissioned_as,
            pid,
            proc_create_time,
            intent: executor_result.intent ?? { kind: 'launch_intent', at },
            at,
          });
        } else if (dossier) {
          dossier.launch = {
            pid,
            proc_create_time,
            at,
            intent: executor_result.intent ?? null,
          };
        }
      }
    }
  }

  const success = {
    ok: true,
    spelling: SPELLING,
    job,
    job_id,
    commissioned_as,
    who,
    proposal_hash: expectedHash,
    client_event_id,
    roadmap,
    roadmap_event,
    projection,
    strip,
    strip_appended,
    strip_instrument,
    dossier,
    durable,
    confirm_journal,
    sot_written,
    bind_appended: true,
    launched,
    processes_launched,
    pid,
    proc_create_time,
    confirmed_and_unlaunched,
    no_executor_host,
    silently_queued: false,
    executor_result,
    single_writer: ROADMAP_SINGLE_WRITER,
    compose: ANCHOR_JOB_COMPOSE,
    runner: ANCHOR_JOB_COMPOSE.runner,
    idempotent: false,
    already_confirmed: false,
    message: no_executor_host
      ? COMMISSION_TEXT[COMMISSION_CODE.NO_EXECUTOR_HOST]
      : `Commission confirmed by ${who.claimed}: ${commissioned_as} bound to step '${proposal.step_id}'${launched ? ' and launched' : ' (queued)'}.`,
  };

  // When no-executor-host, surface the named code while keeping ok-ish confirmed state
  if (no_executor_host) {
    const named = {
      ...success,
      // Confirmed succeeded; launch refused by name — dual status
      ok: true,
      code: COMMISSION_CODE.NO_EXECUTOR_HOST,
      status: COMMISSION_CODE.NO_EXECUTOR_HOST,
      status_code: COMMISSION_CODE.NO_EXECUTOR_HOST,
      text: COMMISSION_TEXT[COMMISSION_CODE.NO_EXECUTOR_HOST],
      user_text: COMMISSION_TEXT[COMMISSION_CODE.NO_EXECUTOR_HOST],
      confirmed: true,
      launched: false,
    };
    _idempotenceCache.set(idemKey, named);
    return named;
  }

  _idempotenceCache.set(idemKey, success);
  return success;
}

export function confirmKickoffSpoken(projectPath, opts = {}) {
  const root = path.resolve(projectPath);
  const providedHash = String(opts.proposal_hash ?? '').trim();
  const lineage = readKickoffLineage(root);
  if (!lineage.ok) return { ...lineage, lane: 'store', mirror: null };

  const named = lineage.proposals.find((proposal) => proposal.proposal_hash === providedHash) ?? null;
  if (!named) {
    const legacy = confirmKickoff(root, {
      proposal_hash: providedHash,
      prior_confirmed_hash: opts.prior_confirmed_hash,
      who: opts.who,
      client_event_id: opts.client_event_id,
      project_id: opts.project_id,
      at: opts.at,
    });
    return { ...legacy, lane: 'roadmap', store_state: lineage.state, mirror: null };
  }

  let proseHash = String(opts.rendered_prose_hash ?? '').trim();
  const resolved = !proseHash;
  if (resolved) proseHash = named.rendered_prose_hash;
  const receipt = confirmKickoffProposal(root, {
    who: opts.who,
    proposal_hash: providedHash,
    rendered_prose_hash: proseHash,
    client_event_id: opts.client_event_id,
    at: opts.at,
    timeoutMs: opts.timeoutMs,
  });
  if (!receipt.ok) return { ...receipt, lane: 'store', mirror: null };

  // The Wave 4 writer: the Face and projection.json are re-derived from the receipt at
  // every matching confirmation - byte-identical on a repeat, so double-confirm is
  // harmless downstream. A refused receipt above never reaches this line, which is what
  // keeps the Face absent on open, rejected, and stale paths.
  const storeProjection = writeKickoffProjection(root, { timeoutMs: opts.timeoutMs });

  const mirror = opts.mirror === false
    ? null
    : mirrorConfirmedKickoffToRoadmap(root, receipt.proposal, {
      who: opts.who,
      client_event_id: receipt.receipt?.client_event_id ?? opts.client_event_id,
      project_id: opts.project_id,
      at: opts.at,
    });
  return {
    ...receipt,
    lane: 'store',
    rendered_prose_hash_resolved_from_store: resolved,
    mirror,
    face_created_on: KICKOFF_FACE_CREATED_ON,
    store_projection: storeProjection,
    projection_written: storeProjection.ok === true && storeProjection.projection_written === true,
    face_written: storeProjection.ok === true && storeProjection.face_written === true,
    projection: mirror?.projection ?? null,
    projection_pending: mirror ? mirror.ok !== true || mirror.projection_pending === true : false,
    plan_entries_written: mirror?.plan_entries_written ?? 0,
  };
}

export function verbRefinementUpdate(opts={}) {
  try {
    const input=opts.refinement_operation || JSON.parse(fs.readFileSync(0,'utf8'));
    if(input.action==='capabilities') return {ok:true,capabilities:{schema:REFINEMENT_SCHEMA,version:1,
      actions:['producer_handoff','resolve_handoff','visual_companion'],
      individual_completion:true,approved_collection:true,provisional_publish:true}};
    const root=path.resolve(opts.project || '.');
    const loaded=loadProjectRoadmap(root);
    if(!loaded.ok || !loaded.exists) return fail(loaded.exists?'backing-store-unreadable':'empty-but-valid');
    if(input.action==='read') return refinementResult(root,loaded.roadmap);
    if(input.action==='repair') {
      return repairRoadmapProjectionsThroughSpine(root,{timeoutMs:opts.timeoutMs});
    }
    if(input.action==='operation_status') {
      const found=loaded.roadmap.roadmap_events.find(e=>e.kind==='refinement_update'&&e.operation?.operation_id===input.operation_id);
      const result=refinementResult(root,loaded.roadmap);
      return {...result,operation_id:input.operation_id,committed:!!found,result:found?{...result,committed:true,operation_id:input.operation_id}:undefined};
    }
    if(!input.operation_id || !Number.isInteger(input.expected_seq)) return fail('operation-id-and-sequence-required');
    if(input.action==='close') {
      // cockpit Wave B: the steward's close states the next act and the goal re-read first
      const demand=demandClose(root,loaded.roadmap,input.step_id,input.goal_reread??null);
      if(!demand.ok) return demand;
    }
    const result=appendRoadmapEventThroughSpine(root,{kind:'refinement_update',at:new Date().toISOString(),client_event_id:input.operation_id,request_digest:refinementDigest(input),operation:input},{skip_index:true});
    if(!result.ok) return result;
    const view=refinementResult(root,result.roadmap);
    return {...view,committed:true,operation_id:input.operation_id,idempotent:result.idempotent};
  } catch(e) { return fail(e.code || 'invalid-refinement-operation',e.message); }
}

case 'feedback': {
  const review = elegance(operation.elegance, 'RC6');
  identifier(operation.feedback_id, 'feedback_id');
  demand(!slice.feedback.some(item => item.id === operation.feedback_id),
    'DUPLICATE_FEEDBACK', 'Feedback ID already exists.');
  demand(nonempty(operation.source_message), 'FEEDBACK_SOURCE_REQUIRED', 'Feedback requires its source message.');
  if (slice.presentations.length > 0 || operation.base_presentation_id != null) {
    getPresentation(slice, operation.base_presentation_id);
  }
  demand(Array.isArray(operation.changes), 'INVALID_REQUIREMENTS', 'Feedback changes must be an array.');
  if (currentRound(slice).presentations.length > 0) {
    slice.round += 1;
    slice.rounds.push({ index: slice.round, feedback_ids: [], presentations: [] });
  }
  const priorRequirements = new Set(Object.keys(slice.requirements));
  const superseded = new Set();
  const feedback = {
    id: operation.feedback_id, source_message: operation.source_message,
    base_presentation_id: operation.base_presentation_id ?? null,
    round: slice.round, disposition: 'pending', changes: [],
    at: state.last_event_at, generation: state.generation,
  };
  for (const change of operation.changes) {
    identifier(change?.id, 'requirement id');
    demand(!Object.hasOwn(slice.requirements, change.id),
      'REQUIREMENT_EXISTS', 'Requirement IDs are immutable; use a new ID and explicit supersedes.');
    demand(nonempty(change.scope) && nonempty(change.text) &&
      ['require', 'preserve', 'exclude'].includes(change.directive),
    'INVALID_REQUIREMENT', 'Each requirement needs scope, text and a supported directive.');
    if (change.supersedes !== undefined) {
      identifier(change.supersedes, 'supersedes');
      demand(priorRequirements.has(change.supersedes) && !superseded.has(change.supersedes),
        'INVALID_SUPERSESSION', 'Supersedes must identify one existing prior requirement, once per feedback.');
      demand(!Object.values(slice.requirements).some(item =>
        item.supersedes === change.supersedes && ['pending', 'active'].includes(item.status)),
      'SUPERSESSION_CONFLICT', 'An active or unresolved replacement already supersedes that requirement.');
      superseded.add(change.supersedes);
    }
    slice.requirements[change.id] = {
      id: change.id, scope: change.scope, directive: change.directive, text: change.text,
      ...(change.supersedes !== undefined ? { supersedes: change.supersedes } : {}),
      feedback_id: feedback.id, source_message: feedback.source_message,
      round: slice.round, status: 'pending',
    };
    feedback.changes.push(change.id);
  }
  slice.feedback.push(feedback);
  currentRound(slice).feedback_ids.push(feedback.id);
  unclose(slice, state.generation, 'new_feedback');
  slice.work_phase = 'revising';
  supersedeRequests(state, slice, 'new_feedback');
  recordElegance(slice, review, operation.action, state);
  break;
}

case 'publish': {
  const review = elegance(operation.elegance, 'RC6');
  requireOpenRound(slice);
  if (operation.provisional !== undefined) {
    humanEvidence(operation.provisional?.human);
    demand(nonempty(operation.provisional.scope) && nonempty(operation.provisional.reason),
      'PROVISIONAL_SCOPE_REQUIRED', 'Partial work needs explicit human scope and a prerequisite explanation.');
  } else foundationsClosed(state, slice);
  demand(Array.isArray(operation.products) && operation.products.length > 0,
    'INVALID_PRODUCTS', 'Publish requires at least one product revision.');
  const seen = new Set();
  for (const product of operation.products) {
    identifier(product?.product_id, 'product_id');
    identifier(product.revision_id, 'revision_id');
    demand(slice.product_ids.includes(product.product_id), 'UNKNOWN_PRODUCT', 'Product is not owned by this slice.');
    demand(!seen.has(product.product_id), 'DUPLICATE_PRODUCT', 'Publish cannot include the same product twice.');
    seen.add(product.product_id);
    demand(!Object.values(state.slices).some(item => Object.hasOwn(item.revisions, product.revision_id)),
      'REVISION_EXISTS', 'Revision IDs are immutable and globally unique.');
    demand(typeof product.hash === 'string' && /^[a-f0-9]{64}$/i.test(product.hash) && nonempty(product.path),
      'INVALID_REVISION', 'A revision needs a SHA256 digest and immutable file locator.');
    if(product.source_history!==undefined) demand(slice.presentations.length===0 && object(product.source_history) &&
      Number.isInteger(product.source_history.iteration) && product.source_history.iteration>=0 &&
      product.source_history.iteration<=10000 && !Object.values(slice.revisions).some(r=>r.product_id===product.product_id &&
        r.source_history && r.source_history.iteration>=product.source_history.iteration) &&
      nonempty(product.source_history.source) && nonempty(product.source_history.at),
      'INVALID_SOURCE_HISTORY','Imported iterations require their actual source and date.');
    const expectedParent = slice.candidate[product.product_id] ?? null;
    const parent = product.parent_revision_id ?? null;
    if (parent !== expectedParent) {
      const rollback = product.rollback_source;
      const sourceRevision = object(rollback) ? slice.revisions[rollback.revision_id] : null;
      demand(sourceRevision && sourceRevision.product_id === product.product_id &&
        parent === sourceRevision.revision_id && nonempty(rollback.source),
      'INVALID_REVISION_PARENT', 'Parent must be the current candidate or an explicitly sourced rollback revision.');
    } else if (product.rollback_source !== undefined) {
      const rollback = product.rollback_source;
      demand(object(rollback) && nonempty(rollback.source) &&
        slice.revisions[rollback.revision_id]?.product_id === product.product_id,
      'INVALID_ROLLBACK_SOURCE', 'Rollback source must identify an existing revision of the same product.');
    }
    slice.revisions[product.revision_id] = {
      product_id: product.product_id, revision_id: product.revision_id,
      hash: product.hash.toLowerCase(), path: product.path,
      parent_revision_id: parent, previous_candidate_revision_id: expectedParent,
      ...(product.rollback_source ? { rollback_source: clone(product.rollback_source) } : {}),
      round: slice.round, at: state.last_event_at, generation: state.generation,
      ...(operation.provisional ? {provisional:clone(operation.provisional)} : {}),
      ...(product.source_history ? {source_history:clone(product.source_history)} : {}),
    };
    slice.candidate[product.product_id] = product.revision_id;
  }
  slice.work_phase = slice.round === 0 ? 'preparing' : 'revising';
  recordElegance(slice, review, operation.action, state);
  break;
}

case 'present': {
  demand(operation.product_context_version===undefined || operation.product_context_version===1,
    'INVALID_PRODUCT_CONTEXT_VERSION','Unsupported product applicability context.');
  const review = elegance(operation.elegance, 'RC6');
  requireOpenRound(slice);
  dependenciesCurrent(state, slice);
  demand(slice.feedback.every(item => item.disposition !== 'pending'),
    'UNRESOLVED_FEEDBACK', 'Every feedback item needs an explicit disposition before presentation.');
  const presentationId = identifier(operation.presentation_id, 'presentation_id');
  const requestId = identifier(operation.request_id, 'request_id');
  demand(!Object.values(state.slices).some(item => item.presentations.some(p => p.id === presentationId)),
    'PRESENTATION_EXISTS', 'Presentation IDs are immutable and globally unique.');
  demand(!Object.values(state.slices).some(item => item.review_requests.some(r => r.id === requestId)),
    'REQUEST_EXISTS', 'Review request IDs are globally unique.');
  demand(nonempty(operation.source_message) && nonempty(operation.purpose),
    'REVIEW_REQUEST_SOURCE_REQUIRED', 'Presentation requires a source message and concrete review purpose.');
  const members = candidateMembers(slice);
  const candidateDigest = refinementDigest(slice.candidate);
  const requirementsDigest = refinementDigest(slice.requirements);
  demand(Array.isArray(operation.checks) && operation.checks.some(check => check.kind === 'content'),
    'CONTENT_REVIEW_REQUIRED', 'A sourced semantic content review is required for each presentation.');
  for (const check of operation.checks) {
    demand(object(check) && ['content', 'tests'].includes(check.kind) &&
      check.outcome === 'pass' && nonempty(check.source),
    'INVALID_CHECK', 'Checks must pass and identify their evidence source.');
    demand(check.candidate_digest === candidateDigest && check.requirements_digest === requirementsDigest,
      'STALE_CHECK', 'Checks must refer to the exact candidate and cumulative requirement state.');
  }
  const presentation = {
    id: presentationId, round: slice.round, at: state.last_event_at, generation: state.generation,
    members, requirements_digest: requirementsDigest, candidate_digest: candidateDigest,
    applicable_requirements_digest: refinementDigest(activeRequirements(slice)),
    ...(operation.product_context_version===1 ? {product_context:{version:1,
      requirements_digests:Object.fromEntries(slice.product_ids.map(id=>[id,productRequirementsDigest(slice,id)]))}} : {}),
    dependency_pins: clone(dependencyContext(slice)),
    dependencies_digest: refinementDigest(dependencyContext(slice)),
    feedback_count: slice.feedback.length, checks: clone(operation.checks),
    elegance: review,
  };
  slice.presentations.push(presentation);
  currentRound(slice).presentations.push(presentationId);
  slice.checks.push(...clone(operation.checks).map(check => ({ ...check, presentation_id: presentationId })));
  const request = {
    id: requestId, step_id: slice.step_id, presentation_id: presentationId,
    members: clone(members), source_message: operation.source_message,
    purpose: operation.purpose, status: 'pending',
  };
  slice.review_requests.push(request);
  slice.work_phase = 'awaiting_review';
  recordElegance(slice, review, operation.action, state);
  break;
}

case 'accept': {
  demand(operation.complete_current === undefined || typeof operation.complete_current === 'boolean',
    'INVALID_COMPLETION_OPTION', 'complete_current must be Boolean.');
  const human = humanEvidence(operation.human);
  const presentation = getPresentation(slice, operation.presentation_id);
  if(operation.complete_current===true && operation.member_product_id && presentation.product_context) {
    dependenciesCurrent(state,slice);
    demand(productApplicable(slice,presentation,operation.member_product_id),'REQUIREMENTS_CHANGED',
      'The named product does not match its applicable cumulative requirements.');
  } else requireApplicablePresentation(state, slice, presentation);
  let member = null;
  if (operation.member_product_id !== undefined) {
    member = presentation.members.find(item => item.product_id === operation.member_product_id);
    demand(member, 'UNKNOWN_PRESENTATION_MEMBER', 'The named product is absent from this presentation.');
    slice.accepted_members[member.product_id] = {
      presentation_id: presentation.id, revision_id: member.revision_id,
      human, generation: state.generation, at: state.last_event_at,
    };
  } else {
    slice.accepted_presentation = presentation.id;
  }
  slice.acceptance_history.push({
    presentation_id: presentation.id, member_product_id: member?.product_id ?? null,
    human, generation: state.generation, at: state.last_event_at,
  });
  // Opt-in semantics for new events only: replay of earlier approvals stays unchanged.
  // Each latest product decision must still apply to the exact current work.
  if (operation.complete_current === true && member &&
      lastPresentation(slice)?.id === presentation.id && presentation.round === slice.round &&
      refinementDigest(slice.candidate) === presentation.candidate_digest &&
      refinementDigest(slice.requirements) === presentation.requirements_digest &&
      slice.feedback.length === presentation.feedback_count &&
      slice.feedback.every(item => item.disposition !== 'pending')) {
    const complete=Object.values(currentProductApprovals(slice)).every(Boolean);
    if (complete) {
      slice.accepted_presentation = presentation.id;
      slice.closed_presentation = presentation.id;
      slice.work_phase = 'done';
      slice.closure_history.push({presentation_id:presentation.id, human,
        source:'individual-acceptances', generation:state.generation, at:state.last_event_at});
      for (const request of slice.review_requests) if (request.presentation_id === presentation.id) {
        request.status = 'resolved'; request.resolved_generation = state.generation;
      }
    }
  }
  // Named historical acceptance is valid without completing a newer round.
  break;
}
case 'visual_companion': {
  const revision = slice.revisions[operation.revision_id];
  demand(revision && revision.hash === operation.source_hash, 'PREVIEW_SOURCE_MISMATCH',
    'A visual companion must identify the exact preserved source revision.');
  demand(object(operation.preview) && /^[a-f0-9]{64}$/.test(operation.preview.hash) &&
    nonempty(operation.preview.path) && operation.preview.path.toLowerCase().endsWith('.pdf') &&
    nonempty(operation.evidence), 'PREVIEW_EVIDENCE_REQUIRED', 'A PDF companion needs its digest and same-version evidence.');
  demand(!revision.visual_companion || refinementDigest(revision.visual_companion) ===
    refinementDigest({...operation.preview,source_hash:operation.source_hash,evidence:operation.evidence}),
    'PREVIEW_ALREADY_BOUND', 'A visual companion cannot silently replace an existing version binding.');
  revision.visual_companion = {...clone(operation.preview),source_hash:operation.source_hash,evidence:operation.evidence};
  break;
}
case 'view': {
  const presentation = getPresentation(slice, operation.presentation_id);
  const request = slice.review_requests.find(item => item.id === operation.request_id);
  demand(request && request.presentation_id === presentation.id, 'VIEW_REQUEST_MISMATCH',
    'A view receipt must name the request associated with the frozen presentation.');
  const member = presentation.members.find(item => item.product_id === operation.member_product_id);
  demand(member && operation.hash === member.hash, 'VIEW_MEMBER_MISMATCH',
    'A view receipt must identify the exact frozen member and digest.');
  demand(nonempty(operation.session_id) && operation.source === 'cockpit-user-open',
    'INVALID_VIEW_SOURCE', 'A view receipt requires an explicit cockpit open and session ID.');
  slice.views.push({
    step_id: slice.step_id, presentation_id: presentation.id, request_id: request.id,
    member_product_id: member.product_id, revision_id: member.revision_id,
    hash: member.hash, session_id: operation.session_id, source: operation.source,
    generation: state.generation, at: state.last_event_at,
  });
  break;
}
case 'close': {
  const human = humanEvidence(operation.human);
  const presentation = getPresentation(slice, operation.presentation_id);
  demand(lastPresentation(slice)?.id === presentation.id && presentation.round === slice.round,
    'NOT_CURRENT_PRESENTATION', 'Only the current round and latest presentation can be closed.');
  demand(slice.candidate && refinementDigest(slice.candidate) === presentation.candidate_digest &&
    refinementDigest(slice.requirements) === presentation.requirements_digest &&
    slice.feedback.length === presentation.feedback_count,
  'PRESENTATION_CHANGED', 'Current candidate or feedback changed after presentation.');
  demand(slice.feedback.every(item => item.disposition !== 'pending'), 'UNRESOLVED_FEEDBACK',
    'Unresolved feedback prevents closure.');
  requireApplicablePresentation(state, slice, presentation);
  slice.accepted_presentation = presentation.id;
  slice.closed_presentation = presentation.id;
  slice.work_phase = 'done';
  slice.acceptance_history.push({
    presentation_id: presentation.id, member_product_id: null,
    human, generation: state.generation, at: state.last_event_at,
  });
  slice.closure_history.push({
    presentation_id: presentation.id, human, generation: state.generation, at: state.last_event_at,
  });
  for (const request of slice.review_requests) {
    if (request.presentation_id === presentation.id) {
      request.status = 'resolved';
      request.resolved_generation = state.generation;
    }
  }
  break;
}

